function save(){try{if(localStorage.getItem('bookwiz-v1')!==storageSnapshot){storageFailed=true;updateSaveStatus('Another tab saved · export before reload',true);toast('Another tab changed this workspace. Export your current work, then reload to avoid overwriting it.');showStorageIssue();return false;}saveState(state);scheduleWidgets();storageSnapshot=localStorage.getItem('bookwiz-v1');storageFailed=false;updateSaveStatus('Saved on this device');document.querySelector('.storage-banner')?.remove();syncCompanion({projectId:project()?.id||'',title:project()?.title||'',wordCount:project()&&!project().sample?count(project()):0});return true;}catch{storageFailed=true;toast('Device storage is full or unavailable. Export a backup before closing.');updateSaveStatus('Not saved · export a backup',true);showStorageIssue();return false;}}
function updateSaveStatus(text,error=false){document.querySelectorAll('.save-state').forEach(el=>el.textContent=text);const status=document.querySelector('.local-state');if(status){status.dataset.status=error?'error':'saved';status.querySelector('.save-indicator').innerHTML=I(error?'shield':'check');}}
function showStorageIssue(){if(document.querySelector('.storage-banner')||!document.querySelector('#main'))return;const el=document.createElement('div');el.className='storage-banner';el.setAttribute('role','alert');el.innerHTML=`<span>These changes are kept in this tab only. Export a backup before closing or reloading.</span>${B('export-workspace','Back up now','download','secondary')}`;document.querySelector('#main').prepend(el);}
function cleanHTML(html){return sanitizeHTML(html); }
state.projects.forEach(p=>{if(p.draftingJob?.state==='running'){p.draftingJob.state='paused';p.draftingJob.reason='The app was closed. Your saved passages are ready to resume.';}p.characters??=[];p.bible??=[];p.worlds??=[];p.language??='English';p.notes??=[];p.references??=[];p.trim=trims[p.trim]||p.trim==='Custom'?p.trim:'Trade paperback';p.target=Number(p.target)||65000;p.author=String(p.author||'Writer');p.premise=String(p.premise||'');if(p.image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.image))delete p.image;if(!p.chapters.length)p.chapters.push({id:uid(),title:'Chapter 1',beat:'',text:'',status:'Planned'});p.chapters.forEach(c=>{c.id??=uid();c.text=cleanHTML(c.text);});p.lastChapter=Math.max(0,Math.min(Number.isInteger(p.lastChapter)?p.lastChapter:0,p.chapters.length-1));p.revisions=(Array.isArray(p.revisions)?p.revisions:[]).filter(r=>r&&typeof r.text==='string'&&typeof r.title==='string');});
chapterIndex=Math.max(0,Math.min(project()?.lastChapter||0,(project()?.chapters.length||1)-1));
