function render(){captureRoom(app);captureWritingAnchor();const previousMain=document.querySelector('#main'),previousScroll={view:previousMain?.dataset.view,top:previousMain?.scrollTop||0,left:previousMain?.scrollLeft||0};if(route==='apps'||location.hash==='#apps'){try{window.history.replaceState(null,'','#'+route);}catch{}}if(activeId){if(!chatSessions.has(activeId))chatSessions.set(activeId,[]);chat=chatSessions.get(activeId);}else chat=[];if(route==='studio'&&studioTab==='draft'&&project()){const c=project().chapters[chapterIndex]||project().chapters[0];if(!writingAnchor||writingAnchor.bookId!==activeId||writingAnchor.chapterId!==c.id)writingAnchor={bookId:activeId,chapterId:c.id,scroll:0};}pageTrail.remember(previousMain?.dataset.trail,previousScroll.top);pageTrail.prune(v=>(v.route!=='wizard'||!!wizard)&&(!['studio','reader','covers'].includes(v.route)||state.projects.some(p=>p.id===v.activeId)));pageTrail.visit(pageLocation());applyAppearance(state.settings);document.body.classList.toggle('reading-mode',route==='reader');let body=route==='library'?library():route==='wizard'?wizardHTML():route==='studio'?studio():route==='hub'?hub():route==='covers'?covers():route==='reader'?readerHTML():route==='settings'?settings():route==='apps'?appsPage({I,B}):route==='support'?supportPage({I,B}):legal();draftFlowView?.dispose();draftFlowView=null;app.innerHTML=shell(body);const motionView=[route,route==='settings'?settingTab:route==='studio'?studioTab:route==='wizard'?wizard?.step:''].join(':');const shouldArrive=motionView!==lastMotionView;decorateMotion(app,route==='hub'?'connection':route==='covers'?'press':route==='settings'||route==='studio'?'pen':'pages',false);lastMotionView=motionView;const main=document.querySelector('#main'),scrollView=[motionView,['studio','reader','covers'].includes(route)?activeId:'',['studio','reader'].includes(route)?chapterIndex:''].join(':');document.documentElement.toggleAttribute('data-writing-navigation',!!document.querySelector('.workspace-navigation'));main.dataset.view=scrollView;settleRoom(app,{view:scrollView,animate:shouldArrive});main.dataset.trail=pageTrail.current.key;if(pendingPageScroll!==null){main.scrollTop=pendingPageScroll;pendingPageScroll=null;}else if(previousScroll.view===scrollView){main.scrollTop=previousScroll.top;main.scrollLeft=previousScroll.left;}document.documentElement.toggleAttribute('data-menu-open',menuOpen);bindEditor();if(route==='studio'&&studioTab==='flow'&&project())openDraftFlowView();renderBusyUI();refreshCacheSummary();if(storageFailed)showStorageIssue();if(route==='hub'&&!localModelTask&&(localModelState.phase==='idle'||Date.now()-lastLocalCheck>30000))void scanLocalModels();}
function art(color){if(color==='field')return `<svg viewBox="0 0 130 100"><g stroke="#60704c" stroke-width="1" fill="none"><path d="M61 99V5m0 50C30 60 23 37 27 25c24-2 33 12 34 30zm1 13c36 3 44-20 39-35-30 0-39 18-39 35z M60 89C31 88 20 76 20 65c24-6 35 10 40 24z"/><path d="m30 28 31 27m36-17L62 67m-37 1 35 20"/></g></svg>`;if(color==='light')return `<svg viewBox="0 0 130 100"><circle cx="74" cy="45" r="28" fill="#e7c78c"/><path d="M9 100 54 18 54 100" fill="#f0dbb5" opacity=".75"/><path d="M54 18 78 100H54z" fill="#5c4136" opacity=".65"/></svg>`;return `<svg viewBox="0 0 130 100"><circle cx="87" cy="30" r="20" fill="#d0cba5" opacity=".85"/><g fill="none" stroke="#9caca2" stroke-width=".6" opacity=".7">${Array.from({length:13},(_,i)=>`<path d="M-10 ${58+i*4}Q52 ${25+i*5} 140 ${64+i*3}"/>`).join('')}</g></svg>`;}
function cover(p,back=false){const[w,h]=trimOf(p),tag=route==='covers'?'button':'div';return `<${tag} class="book-cover vector-cover" style="aspect-ratio:${w}/${h}" ${tag==='button'?`type="button" data-action="${back?'view-back':'view-front'}" aria-label="View ${back?'back':'front'} cover"`:""}>${coverSvg(p,back)}</${tag}>`;}
function projectCard(p){const n=count(p),pct=Math.min(100,Math.round(n/p.target*100)),drafted=p.chapters.filter(c=>words(plain(c.text))>0).length;return `<article class="project-card"><div class="cover-stage ${p.color==='field'?'theme-field':esc(p.color||'sea')}" data-action="open-project" data-id="${p.id}" role="button" tabindex="0" aria-label="Open ${esc(p.title)}">${p.sample?'<span class="cover-badge">Reading sample</span>':''}${cover(p)}</div><div class="project-info"><div class="row between card-title-row"><button class="project-title" data-action="open-project" data-id="${p.id}">${esc(p.title)}</button><button class="icon-btn" data-action="project-menu" data-id="${p.id}" aria-label="Options for ${esc(p.title)}">${I('more')}</button></div><div class="row between" style="margin-top:5px;gap:6px"><span class="genre">${esc(p.genre)}</span><span class="badge ${n?'':'neutral'}">${p.archived?'Archived':p.chapters[0]?.status||'Planned'}</span></div><div class="progress" role="progressbar" aria-label="Word target" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.max(n?2:0,pct)}%"></span></div><div class="project-stats"><span>${n.toLocaleString()} <span class="muted">/ ${(p.target/1000).toFixed(0)}k words</span></span><span>${drafted} of ${p.chapters.length} chapters</span></div><div class="card-bottom"><span>${I('clock')} ${p.sample?'A BookWiz original':new Date(p.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><button data-action="open-project" data-id="${p.id}">Continue writing ${I('arrow')}</button></div></div></article>`;}
function libraryBooks(){const ps=state.projects.filter(p=>(libraryTab==='archived'?p.archived:!p.archived)&&(libraryTab!=='drafts'||p.chapters.some(c=>c.text))&&p.title.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>state.settings.librarySort==='title'?a.title.localeCompare(b.title):state.settings.librarySort==='progress'?count(b)/b.target-count(a)/a.target:b.updated-a.updated);return `${ps.map(projectCard).join('')}${libraryTab!=='archived'&&!query?`<button class="new-project-card" data-action="new-project"><span class="plus">${I('plus')}</span><strong>A new story starts here</strong><p>Give your next idea a home.</p></button>`:''}${!ps.length&&(query||libraryTab==='archived')?`<div class="empty">${I('book')}<h2>${query?'No matching books':'A little room on the shelf'}</h2><p>${query?'Try another title.':'Archived books will appear here.'}</p></div>`:''}`;}
function writingPulse(){const week=weeklyActivity(state.activity);return `<section class="writing-pulse" aria-label="A line for today"><div><span class="section-eyebrow">A LINE FOR TODAY</span><blockquote>${esc(dailyQuote())}</blockquote><small>An original BookWiz writing note</small></div><div class="week-progress"><strong>${week.words.toLocaleString()}</strong><span>words in the last seven days</span><small>${week.days} writing ${week.days===1?'day':'days'} · your own pace</small>${B('quick-note','Catch a thought','note','quiet')}</div></section>`;}
function library(){const ps=state.projects.filter(p=>!p.archived),n=ps.reduce((v,p)=>v+count(p),0);return `<div class="page library-page"><div class="page-intro"><div><h1>Room for your next chapter.</h1><p>Your books, your drafts, and the words only you can write.</p></div>${B('new-project','New book','plus','primary')}</div>${resumePanel(ps)}<div class="library-toolbar"><div class="tabs" role="tablist" aria-label="Project filters">${[['all','All books'],['drafts','In progress'],['archived','Archived']].map(([v,l])=>`<button role="tab" aria-selected="${libraryTab===v}" class="${libraryTab===v?'active':''}" data-action="library-tab" data-value="${v}">${l}${v==='all'?`<span class="tabnum">${ps.length}</span>`:''}</button>`).join('')}</div><div class="tools"><select id="library-sort" class="sort-control" aria-label="Sort books"><option value="recent" ${state.settings.librarySort!=='title'&&state.settings.librarySort!=='progress'?'selected':''}>Recent</option><option value="title" ${state.settings.librarySort==='title'?'selected':''}>Title A–Z</option><option value="progress" ${state.settings.librarySort==='progress'?'selected':''}>Progress</option></select><label class="search">${I('search')}<input id="project-search" type="search" aria-label="Search your books" value="${esc(query)}" title="Search your books"></label><div class="view-toggle">${['grid','list'].map(v=>`<button data-action="view" data-value="${v}" class="${view===v?'active':''}" aria-label="${v} view" aria-pressed="${view===v}">${I(v)}</button>`).join('')}</div></div></div><section id="books" aria-label="Your books" class="book-grid ${view==='list'?'list-mode':''}">${libraryBooks()}</section>${writingPulse()}<div class="overview"><div class="metric">${I('book')}<div><strong>${ps.length}</strong><label>Books</label></div></div><div class="metric">${I('pen')}<div><strong>${n.toLocaleString()}</strong><label>Words written</label></div></div><div class="metric">${I('file')}<div><strong>${ps.reduce((v,p)=>v+p.chapters.filter(c=>c.text).length,0)}</strong><label>Drafted chapters</label></div></div><div class="metric">${I('target')}<div><strong>${state.activity[today()]||0}<span style="font-size:11px;color:var(--muted)"> / ${state.settings.dailyGoal}</span></strong><label>Daily goal</label></div></div></div><footer class="library-footer"><span class="row gap8">${I('shield')}Your library lives on this device. Your stories belong to you.</span><span>Made for the words only you can write.</span></footer></div>`;}
function opts(arr,current){return arr.map(v=>`<option ${v===current?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');}
function hub(){const list=providers.filter(p=>(hubTab==='all'||hubTab==='local'&&p.local||hubTab==='image'&&p.image||hubTab==='text'&&p.protocol!=='image'&&!p.local)&&p.name.toLowerCase().includes(query.toLowerCase()));return `<div class="page"><div class="page-intro"><div><h1>AI & model hub</h1><p>Your tools. Your keys. Your choice of intelligence.</p></div>${B('add-connection','Add connection','plus','primary')}</div><div class="notice row">${I('shield')}<span>Connect directly to your provider. Keys stay in this browser session, or in a passphrase-encrypted vault on this device. No BookWiz relay.</span></div>${localModelsHTML()}${state.connections.length?`<div class="section-heading"><h2>Your connections</h2></div><div class="panel" style="padding-block:5px">${state.connections.map(c=>`<div class="connection"><div class="row between"><div><h3>${esc(c.name)} ${c.id===state.activeConnection?'<span class="badge">Selected</span>':''}</h3><p>${esc(c.model)} · ${c.verified?'Last verified '+new Date(c.verified).toLocaleDateString():'Not verified'} · ${providerFor(c).local&&!c.vault?'On this device':c.vault?'Encrypted on device':'Session key'}</p></div><div class="row gap8">${B('edit-connection','Edit','settings','quiet',`data-id="${c.id}"`)}${B('verify-connection','Verify','','quiet',`data-id="${c.id}"`)}${B('use-connection','Select','','secondary',`data-id="${c.id}"`)}<button class="icon-btn" data-action="remove-connection" data-id="${c.id}" aria-label="Remove connection">${I('trash')}</button></div></div></div>`).join('')}</div>`:''}<div class="section-heading row between"><div><h2>Find your writing companion</h2><p>Free tiers and paid plans. Hosted or close to home.</p></div></div><div class="library-toolbar"><div class="tabs">${[['all','All providers'],['text','Text'],['image','Covers'],['local','Local models']].map(([v,l])=>`<button class="${hubTab===v?'active':''}" data-action="hub-tab" data-value="${v}">${l}</button>`).join('')}</div><label class="search">${I('search')}<input id="provider-search" type="search" aria-label="Search providers" value="${esc(query)}"></label></div><div class="provider-grid" id="providers">${providerCards(list)}</div><div class="section-heading"><h2>Keep the intelligence close</h2><p>Local models, without a cloud account.</p></div><div class="panel"><div class="row between wrap"><div><h3>On-device models & imported model files</h3><p class="small muted" style="margin-top:6px">Set up a local runtime on your computer or learn what your mobile device supports.</p></div>${B('local-guide','Read the local model guide','book')}</div></div></div>`;}
function providerCards(ps){return ps.map(p=>`<button class="provider" style="--provider:${p.color}" data-action="provider-setup" data-id="${p.id}"><div class="row">${providerMark(p.id)}<div><h3>${p.name}</h3><p>${p.local?'Private inference':p.protocol==='image'?'Cover image generation':'Writing & editing'}</p></div></div><div class="row between"><span class="badge neutral">${p.tag}</span><span class="row small gap8">${p.protocol==='native'&&!deviceCapabilities().apple?'Get the app':'Connect'} ${I('arrow')}</span></div></button>`).join('')||'<div class="empty"><p>No providers match this search.</p></div>';}
function openDraftFlowView(){
 const p=project(),chapter=p?.chapters[chapterIndex],root=document.querySelector('#draft-flow');if(!p||!chapter||!root)return;
 const current=()=>{const c=activeConnection();return {bookId:p.id,chapterId:chapter.id,chapterText:chapter.text,plainText:plain(chapter.text),chapterTitle:chapter.title,beat:chapter.beat||'',revision:p.contextRevision||0,title:p.title,language:p.language||'English',languageCode:localeOf(p).code,dir:localeOf(p).dir,story:storyContext(p),previous:plain(p.chapters[chapterIndex-1]?.text||''),connectionId:c?JSON.stringify([c.id,c.provider,c.endpoint,c.model]):'',connected:isTextModel(c),model:c?c.name+' · '+c.model:'',deviceModel:c?.provider==='apple-device'};};
 const present=()=>state.projects.includes(p)&&p.chapters.includes(chapter);
 draftFlowView=mountDraftFlow(root,{value:chapter.draftFlow,context:current,chapters:()=>p.chapters,chapterIndex,onChapter:changeChapter,toast,chooseModel:()=>chooseTextModel(),
  persist:data=>{if(!present())return false;chapter.draftFlow=structuredClone(data);return save();},
  authorise:async()=>{if(draftFlowTask)await draftFlowTask.catch(()=>{});if(busy)throw Error('Another model request is in progress. Stop it before starting Draft Flow.');const c=activeConnection();if(!isTextModel(c))throw Error('Choose a text model in the AI & model hub.');const connectionId=current().connectionId,key=await getKey(c);if(!await consent(c,'your book brief, story guide, reference excerpts, chapter endings, scene direction and story pins for up to six Draft Flow previews in this session'))return null;return {connectionId,model:c.name+' · '+c.model,request:(prompt,options)=>{const previous=draftFlowTask,task=(async()=>{if(previous)await previous.catch(()=>{});if(options.signal?.aborted)throw options.signal.reason;if(busy)throw Error('Another model request is already in progress.');busy=true;try{return await generate(c,key,prompt,flowSystem,900,{...options,allowPartial:true});}finally{busy=false;}})();draftFlowTask=task;return task.finally(()=>{if(draftFlowTask===task)draftFlowTask=null;});}};},
  apply:async(text,stamp)=>{if(!present())throw Error('This chapter is no longer in the library.');const before=chapter.text,currentStamp=await sourceStamp(current());if(!present()||chapter.text!==before||currentStamp!==stamp)throw Error('The chapter changed. Explore a new continuation before keeping this preview.');const snapshot={text:chapter.text,status:chapter.status,updated:p.updated,revisions:structuredClone(p.revisions||[]),contextChanges:structuredClone(p.contextChanges||[]),contextRevision:p.contextRevision,continuityReview:p.continuityReview?structuredClone(p.continuityReview):undefined,continuity:p.chapters.map(c=>c.continuityStatus)};draftHistory.sync(chapterKey(p,chapter),chapter);addRevision(p,chapter,'Before Draft Flow',Date.now(),{includeEmpty:true});chapter.text+=paragraphs(text);chapter.status='Drafting';p.updated=Date.now();if(p.chapters.slice(chapterIndex+1).some(c=>plain(c.text).trim()))registerContextChange(p,'Draft Flow addition','A continuation was kept in '+chapter.title+'. Check later chapters for affected story details.',{fromIndex:chapterIndex+1});if(!save()){chapter.text=snapshot.text;chapter.status=snapshot.status;p.updated=snapshot.updated;p.revisions=snapshot.revisions;p.contextChanges=snapshot.contextChanges;p.contextRevision=snapshot.contextRevision;p.continuityReview=snapshot.continuityReview;p.chapters.forEach((c,i)=>{c.continuityStatus=snapshot.continuity[i];});return false;}draftHistory.sync(chapterKey(p,chapter),chapter);return true;}
 });
}
function studio(){const p=project();if(!p)return `<div class="page empty"><h1>Your writing room is ready</h1><p>Create a book to begin.</p>${B('new-project','Create a book','plus','primary')}</div>`;if(chapterIndex>=p.chapters.length)chapterIndex=0;const c=p.chapters[chapterIndex];return `<div class="studio-tabs"><label class="mobile-studio-picker"><span class="sr-only">Book section</span><select id="studio-section" aria-label="Book section">${[["draft","Write & outline"],["flow","Draft Flow"],["characters","Characters"],["world","World bible"],["notes","Notes"]].map(([v,l])=>`<option value="${v}" ${studioTab===v?"selected":""}>${l}</option>`).join("")}</select></label><div class="mobile-book-tools">${B("studio-more","Book","book","quiet")}</div>${[['draft','Outline & draft'],['flow','Draft Flow'],['characters','Characters'],['world','World bible'],['notes','Notes']].map(([v,l])=>`<button class="${studioTab===v?'active':''}" data-action="studio-tab" data-value="${v}">${l}</button>`).join('')}<button data-action="open-red-pen">${I('pen')} The Red Pen</button><details class="studio-tools"><summary>${I('book')} Book tools ${I('down')}</summary><div aria-label="Book tools">${B('book-brief','Book brief','file','quiet')}${B('preview-book','Preview book','book','quiet')}${B('generate-book','Draft chapters','feather','quiet')}</div></details></div><div id="story-status">${storyBanner(p)}</div>${p.setupStage==='outline'&&!p.outlineAccepted?`<div class="notice setup-return">${B('resume-outline','Return to outline review','arrow','primary')}</div>`:''}${p.proposals?.length?`<div class="notice setup-return">${B('review-proposals',p.proposals.length+' proposed passage(s) to review','file','secondary')}</div>`:''}${studioTab==='flow'?draftFlowHTML():studioTab==='draft'?`<div class="mobile-chapter-picker"><label><span class="sr-only">Current chapter</span><select id="mobile-chapter" aria-label="Current chapter">${p.chapters.map((ch,i)=>`<option value="${i}" ${i===chapterIndex?"selected":""}>${String(i+1).padStart(2,"0")} · ${esc(ch.title)}</option>`).join("")}</select></label>${B("outline","Outline","list","quiet")}</div><div class="studio-shell"><aside class="chapter-panel"><h3>YOUR MANUSCRIPT</h3>${p.chapters.map((ch,i)=>`<button class="chapter-button ${i===chapterIndex?'active':''}" data-action="chapter" data-index="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(ch.title)}</strong><small>${ch.text?words(plain(ch.text))+' words · '+ch.status:'Outline ready'}</small></span></button>`).join('')}${B('add-chapter','Add chapter','plus','quiet')}${B('outline','Chapter outline','list','quiet')}</aside><section class="editor-column"><div class="editor-toolbar"><div class="mobile-editor-tools"><button type="button" data-action="undo-draft" aria-label="Undo">${I("undo")}</button><button type="button" data-format="bold" aria-label="Bold"><b>B</b></button><button type="button" data-format="italic" aria-label="Italic"><i>I</i></button><button type="button" data-action="zen" aria-label="Focus on writing">${I("zen")}</button><details class="editor-tool-menu"><summary aria-label="More writing tools">${I("settings")}<span>Tools</span>${I("down")}</summary><div class="editor-tool-options" role="group" aria-label="Writing tools">${B("redo-draft","Redo","redo","quiet")}<button type="button" data-format="underline"><u>Underline</u></button><button type="button" data-format="formatBlock" data-value="h2">Heading</button><button type="button" data-format="insertUnorderedList">${I("list")} Bullet list</button>${B("find","Find & replace","search","quiet")}${B("polish-chapter","Polish passage","pen","quiet")}${B("version-history","Versions","clock","quiet")}${B("reader","Read","book","quiet")}${B("read-aloud","Listen","volume","quiet")}${B("add-chapter","Add chapter","plus","quiet")}</div></details></div><div class="row gap8"><button type="button" data-action="undo-draft" aria-label="Undo" title="Undo (Ctrl/⌘ Z)">${I('undo')}</button><button type="button" data-action="redo-draft" aria-label="Redo" title="Redo (Ctrl/⌘ Shift Z)">${I('redo')}</button><span class="toolbar-divider"></span><button data-format="bold" aria-label="Bold"><b>B</b></button><button data-format="italic" aria-label="Italic"><i>I</i></button><button data-format="underline" aria-label="Underline"><u>U</u></button><span class="toolbar-divider"></span><button data-format="formatBlock" data-value="h2" aria-label="Heading">H₂</button><button data-format="insertUnorderedList" aria-label="Bullet list">${I('list')}</button><button data-action="find" aria-label="Find and replace">${I('search')}</button></div><div class="row gap8">${B('polish-chapter','Polish','pen','quiet')}${B('version-history','Versions','clock','quiet')}${B('reader','Read','book','quiet')}${B('read-aloud','Listen','volume','quiet')}${B('zen','Focus','zen','quiet')}</div></div><div class="editor-scroll"><div class="editor-paper" dir="${localeOf(p).dir}" lang="${localeOf(p).code}" style="font-family:${esc(designOf(p).font)};--chapter-align:${designOf(p).align}">${c.lastReplyLimited?'<div class="model-limit-note">The last response reached its reply limit. Your passage is kept; Write more continues from here.</div>':''}<div class="chapter-kicker">${esc(localeOf(p).chapter)} ${String(chapterIndex+1).padStart(2,'0')}</div><input class="editor-title" id="chapter-title" value="${esc(c.title)}" aria-label="Chapter title"><div class="manuscript" id="editor" data-book="${esc(p.id)}" data-chapter="${esc(c.id)}" contenteditable="true" role="textbox" aria-label="Manuscript editor" aria-multiline="true" spellcheck="true">${cleanHTML(c.text)}</div></div><div id="editor-model-loading"></div></div><div class="editor-bottom"><div><span id="word-count">${words(plain(c.text)).toLocaleString()}</span> words <span style="margin:0 8px">·</span><span class="save-state">Saved on this device</span></div><div class="row gap8">${B('continue-writing','Write more','feather','secondary')}${B('next-chapter','Next chapter','arrow','primary')}</div></div></section></div>`:`<div class="page">${studioTab==='characters'?entities(p,'characters'):studioTab==='world'?worldBible(p):notes(p)}</div>`}`;}
function entities(p,type){const chars=type==='characters',items=p[type]||[],filtered=type==='bible'&&worldFilter!=='all'?items.map((e,i)=>({e,i})).filter(({e})=>worldFilter==='shared'?!e.worldId:e.worldId===worldFilter):items.map((e,i)=>({e,i}));return `<div class="page-intro"><div><${type==='bible'?'h2':'h1'}>${chars?'The people in your pages':type==='worlds'?'Worlds & settings':'The details of your world'}</${type==='bible'?'h2':'h1'}><p>${chars?'Desires, contradictions, and the things left unsaid.':type==='worlds'?'Distinct places, shared rules, and the connections between them.':'Locations, lore, factions and the objects that matter.'}</p></div><div class="row wrap gap8">${B('add-entity',chars?'Add character':type==='worlds'?'Add world':'Add world detail','plus','primary',`data-value="${type}"`)}${B('suggest-new-entity','Suggest with AI','pen','secondary',`data-value="${type}"`)}</div></div><div class="entity-grid">${filtered.map(({e,i})=>`<article class="panel entity"><div class="row between"><h3>${esc(e.name)}</h3><button class="icon-btn" aria-label="Edit ${esc(e.name)}" data-action="edit-entity" data-value="${type}" data-index="${i}">${I('pen')}</button></div>${e.role||e.type?`<span class="badge">${esc(e.role||e.type)}</span>`:''}${e.worldId?`<p class="entity-world">${esc(p.worlds?.find(w=>w.id===e.worldId)?.name||'Shared story')}</p>`:''}<dl>${entityFields[type].map(([k,l])=>`<dt>${l}</dt><dd>${esc(e[k]||'Not yet explored')}</dd>`).join('')}</dl>${B('refine-entity','Refine with AI','pen','quiet',`data-value="${type}" data-index="${i}"`)}</article>`).join('')||`<div class="empty"><h2>${chars?'Every story needs someone':type==='worlds'?'Make room for a world':'Give your world a foundation'}</h2><p>${chars?'Begin with what they want, and what they cannot say.':'Write your own notes, or ask for a direction to explore.'}</p></div>`}</div>`;}
function worldBible(p){p.worlds??=[];if(worldFilter!=='all'&&worldFilter!=='shared'&&!p.worlds.some(w=>w.id===worldFilter))worldFilter='all';const overview=p.world?`<div class="world-overview"><span class="section-eyebrow">THE SETTING</span><p>${esc(p.world)}</p>${B('book-brief','Edit setting','pen','quiet')}</div>`:'';return entities(p,'worlds').replace('<div class="entity-grid">',overview+'<div class="entity-grid">')+`<div class="world-filter"><label class="field"><span>Show world details</span><select id="world-filter"><option value="all">All worlds</option><option value="shared" ${worldFilter==='shared'?'selected':''}>Shared story</option>${p.worlds.map(w=>`<option value="${esc(w.id)}" ${worldFilter===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label></div>${entities(p,'bible')}`;}
function notes(p){return `<div class="page-intro"><div><h1>Between the lines</h1><p>Premises, passing thoughts, and things to come back to.</p></div>${B('quick-note','Capture a note','plus','primary')}</div><div class="panel"><h3>The premise</h3><p class="small muted" style="margin-top:12px">${esc(p.premise)}</p>${p.styleGuide?`<h3 style="margin-top:25px">Style guide & recurring motifs</h3><p class="small muted" style="margin-top:12px;white-space:pre-wrap">${esc(p.styleGuide)}</p>`:''}<p class="small muted" style="margin-top:20px">${esc(p.world||'')}</p></div>${p.notes.map((n,i)=>`<article class="panel" style="margin-top:15px"><div class="row between"><span class="tiny muted">${new Date(n.date).toLocaleDateString()}</span><button class="icon-btn" data-action="delete-note" data-index="${i}" aria-label="Delete note">${I('trash')}</button></div><p class="small" style="white-space:pre-wrap;margin-top:10px">${esc(n.text)}</p></article>`).join('')}`;}
function drawerHTML(){return `<aside class="ai-drawer red-pen-drawer" aria-label="The Red Pen"><header class="drawer-head row between"><div><span class="section-eyebrow">YOUR EDITOR & CO-AUTHOR</span><h2>The Red Pen</h2></div><button data-action="close-drawer" class="icon-btn" aria-label="Close The Red Pen">${I('close')}</button></header><div class="red-pen-modes" role="group" aria-label="Editorial approach">${[['coach','Co-write'],['critique','Close reading']].map(([v,label])=>`<button data-action="red-pen-mode" data-value="${v}" aria-pressed="${redPenMode===v}">${label}</button>`).join('')}</div><div class="drawer-body" id="chat-messages">${chat.length?chat.map((m,i)=>`<article class="chat-msg ${m.role==='You'?'user':''}"><h4>${m.role==='You'?'You':'The Red Pen'}</h4><p>${esc(m.text)}</p>${m.role!=='You'?`<div class="row wrap">${B('insert-chat','Add as passage','plus','secondary',`data-index="${i}"`)}${B('chat-to-character','Shape a character','users','quiet',`data-index="${i}"`)}${B('chat-to-world','Shape a world detail','world','quiet',`data-index="${i}"`)}</div>`:''}</article>`).join(''):`<div class="red-pen-intro"><p>${redPenMode==='critique'?'A close reading of voice, character, imagery and structure, with exact quotes and practical revisions.':'Talk through a scene, develop your cast or find the next sentence. Your choices lead the story.'}</p></div><div class="red-pen-prompts">${B('chat-prompt','Read this chapter','pen','secondary','data-value="Give this chapter a literary critique. Score voice, character, imagery, structure and originality from 1 to 10. Quote exact passages and suggest precise improvements."')}${B('chat-prompt','Find the next beat','feather','secondary','data-value="What does the next scene need? Suggest three grounded possibilities that preserve the outline and current story facts."')}${B('chat-prompt','Deepen a character','users','secondary','data-value="Suggest a deeper contradiction or motivation for an existing character. Preserve their identity and explain the implications for the story."')}${B('chat-prompt','Explore the world','world','secondary','data-value="Suggest one world detail that adds atmosphere and creates meaningful consequences in this story."')}${B('polish-chapter','Propose a chapter revision','pen','quiet')}</div>`}</div><form id="chat-form" class="drawer-compose"><label class="field"><span>Ask The Red Pen</span><textarea id="chat-input" required rows="3" aria-label="Message The Red Pen"></textarea></label><div class="row between"><span class="tiny muted">${esc(activeConnection()?.name||'Choose an AI connection')}</span>${B('send-chat','Send','arrow','primary',`type="submit" ${busy?'disabled':''}`)}</div></form></aside>`;}
function covers(){const p=project();if(!p)return `<div class="page empty"><h1>A book deserves a cover</h1><p>Create or open a book first.</p>${B('new-project','Create a book','plus','primary')}</div>`;return `<div class="page"><div class="page-intro"><div><h1>Dress your words.</h1><p>One book. A considered cover, front to back.</p></div><div class="cover-header-actions"><label class="cover-book-picker"><span>Saved book to design</span><select id="cover-project" aria-label="Saved book to design">${state.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><small>${state.projects.length} saved ${state.projects.length===1?'book':'books'}</small></label>${B('cover-gallery','Browse 32 cover designs','grid','primary')}</div></div><div class="split cover-split"><div><div class="cover-workspace-label"><span>Cover design: <strong id="current-cover-design">${esc(coverDirection(p.coverDesign).name)}</strong></span><span>Front & back</span></div><div class="cover-workspace" id="cover-preview">${cover(p)}${cover(p,true)}</div><div class="row between small muted" style="padding:15px 3px"><span>Front & back · ${esc(p.trim)}</span><span>${trimOf(p).join(' × ')} in · ${p.image?'AI artwork':'Original vector design'}</span></div></div><form id="cover-form" class="panel stack"><div class="row between wrap"><div><span class="section-eyebrow">${esc(coverDirection(p.coverDesign).category)}</span><h2>${esc(coverDirection(p.coverDesign).name)}</h2></div><span class="badge neutral">Design controls</span></div><p class="small muted">A starting point for something entirely your own.</p>${coverControls(p,B)}<details class="cover-controls"><summary>Book details</summary><div class="stack"><label class="field"><span>Title</span><input name="title" value="${esc(p.title)}" required maxlength="120"></label><label class="field"><span>Subtitle</span><input name="subtitle" value="${esc(p.subtitle||'')}" maxlength="130"></label><label class="field"><span>Author</span><input name="author" value="${esc(p.author)}" required maxlength="100"></label><label class="field"><span>Imprint</span><input name="imprintName" value="${esc(imprintOf(p))}" maxlength="100"></label><label class="field"><span>Back-cover blurb</span><textarea name="blurb" rows="5" maxlength="900">${esc(p.blurb||p.premise)}</textarea></label></div></details><details class="cover-controls"><summary>Curated palettes</summary><div class="cover-palette-list">${[['crimson','#ae383d'],['cobalt','#254e9d'],['ink','#202124'],['ochre','#d9b64c'],['sea','#203c3c'],['field','#dedfc8'],['light','#9e4535'],['archive','#26334d'],['mineral','#d8c9b5'],['plum','#523b4d']].map(([v,c])=>`<button type="button" data-action="cover-color" data-value="${v}" aria-label="${v} palette" aria-pressed="${coverPaletteSelected(p,v)}" style="--cover-swatch:${c}"></button>`).join('')}</div></details><span class="small muted" id="cover-save-status" role="status">Saved on this device</span><div class="row wrap gap8">${B('view-front','View front','cover','quiet','type="button"')}${B('view-back','View back','cover','quiet','type="button"')}</div>${B('save-cover','Save cover','check','primary','type="submit"')}${B('upload-cover-image','Add your artwork','upload','secondary','type="button"')}${B('generate-cover','Generate artwork','cover','secondary','type="button"')}${p.image?B('remove-cover-image','Use vector artwork','cover','quiet','type="button"'):''}<p class="tiny muted">Image generation uses your selected provider. The project QR links to BookWiz, not an ISBN. Check printer bleed and barcode requirements before printing.</p><div class="row wrap">${B('download-front','Front SVG','download','quiet','type="button"')}${B('download-back','Back SVG','download','quiet','type="button"')}</div></form></div><div class="section-heading"><h2>From manuscript to book</h2><p>Take your words with you. You own every page.</p></div><div class="row wrap gap8 publishing-actions">${B('publication-review','Review before publishing','check','primary')}${B('preview-book','Preview every page','book','secondary')}${B('book-brief','Book brief','file','quiet')}</div><div class="export-options">${[['export-epub','EPUB e-book','book','Reflowable chapters, opening pages, cover and navigation.'],['print-book','Print / save PDF','file','Trim-sized, typeset pages through your print dialog.'],['export-tex','LaTeX source bundle','book','Manuscript, front & back covers, and typesetting guide.'],['compile-tex','Compile with LaTeX','pen','Use your private local typesetting service.'],['export-html','Print HTML','file','An independent, beautifully formatted manuscript.'],['export-md','Markdown','download','Clean, portable text for your next writing tool.'],['export-project','Book backup','shield','A complete JSON copy of this project.']].map(([a,t,i,d])=>`<button class="export-option" data-action="${a}">${I(i)}<h3>${t}</h3><p>${d}</p></button>`).join('')}</div><p class="help-line">${I('help')}Print HTML is a proofing layout. Before professional printing, check fonts, page count, bleed, image resolution, and your printer’s specifications.</p></div>`;}
const legalDocs={privacy:{title:'Privacy policy',html:`<p>Effective November 15, 2026. BookWiz is created by muneebwanee. Your unpublished work deserves a private writing room.</p><h2>What stays on your device</h2><p>Projects, chapters, chapter versions, characters, world notes, references, preferences, and optional encrypted API credentials are stored in this browser workspace or your installed app’s private storage. Session-only keys stay in memory until the tab closes. Passphrase-protected keys use AES-GCM encryption with a PBKDF2-derived key. BookWiz cannot recover a forgotten passphrase.</p><h2>Home-screen widgets</h2><p>The installed iPhone/iPad and Android apps share aggregate progress, session deadlines and, only if you enable it, the current book title with their own widgets. Manuscript text, reference files and keys are never included. Widgets use local app storage; Apple uses an App Group shared by this app and its widget extension. Erasing the workspace clears shared progress too.</p><h2>Apps and file access</h2><p>The web edition and installed apps keep separate libraries. Native file opening reads only the backup you choose through the system picker and asks for confirmation before importing copies. No whole-device file access is requested. The Apps page offers the Android package and links to available platform releases. Downloads may require a network connection; Apple installation requires a signed package. Home-screen web shortcuts keep web capabilities. They do not add native widgets, Apple Intelligence or closed-app reminders.</p><h2>Writing reminders</h2><p>Optional reminders are scheduled locally in the iPhone, iPad and Android apps after you enable them and grant notification access. Your selected days, time, quiet hours and pause choice stay on this device. Notification text contains original writing notes, without manuscript text or book titles. At most one reminder is scheduled per selected day for a two-week window, refreshed when you open the app. Turning reminders off or erasing the workspace cancels pending reminders. Delivery depends on operating-system settings; timezone changes may require reopening the app. No push server or engagement tracking is used.</p><h2>Device access</h2><p>Files use the system picker. No location, contacts, camera, tracking or broad photo/storage access is requested. System keyboard dictation follows your operating system’s privacy settings. Apple Intelligence requests run on a compatible device with the model enabled and downloaded. Local network services may require access granted by your device; each model action still asks for approval.</p><h2>When words leave your device</h2><p>BookWiz asks before individual AI requests and explicitly described batches. The selected provider receives the prompt and the context described in the confirmation. That provider’s privacy policy, retention rules, regional processing, and fees apply. Key verification sends a short test prompt. Image generation sends cover instructions. Device voices are listed with their language and local/online status. Online voices require confirmation. Optional Studio narration sends only the chosen sample or chapter to your OpenAI connection in short audio requests after approval; its data policy and speech charges apply. Native read-aloud uses system speech engines without microphone access. Audio stays in temporary memory and is released after playback or stopping; it is not put in the offline cache. Voice and speed preferences stay locally.</p><h2>Local services</h2><p>The model hub automatically reads model-list metadata from known loopback addresses for Ollama, LM Studio and llama.cpp, without sharing manuscript text or API keys. Native Apple apps can check their device model’s availability. LaTeX capability checks contain no manuscript; source is sent only to your local compiler when you choose Compile PDF. Local typesetting stays on this device.</p><h2>No telemetry or tracking</h2><p>The application contains no analytics SDK, ads, third-party tracking pixel, or behavioral telemetry. Fonts and libraries are served with the app. The hosting platform may process essential access, security, IP-address, and request logs under its own privacy terms. Zero application telemetry does not mean the internet or your AI provider creates no records.</p><h2>Your controls</h2><p>Use Settings → Privacy &amp; data to export a backup. Use Settings → Private profile → Delete to erase BookWiz data from this browser. Deletion cannot erase downloaded backups, provider records, or hosting security logs. Clearing browser storage also removes your library. Private browsing and low-storage conditions can cause data loss; keep independent backups.</p><h2>Privacy labels</h2><ul><li>Application analytics: not collected.</li><li>Advertising and cross-app tracking: not used.</li><li>Identity and payment information: not requested by BookWiz.</li><li>User content: stored locally; shared with a chosen AI provider only after approval.</li><li>API credentials: session memory, or encrypted local storage by your choice.</li><li>Microphone, camera, contacts, and location: not requested.</li></ul><h2>Questions</h2><p>Contact the maintainer through <a href="https://github.com/muneebwanee" target="_blank" rel="noopener">github.com/muneebwanee</a>. Never include API keys or private manuscripts in a public support request.</p><h2>Book context and revision requests</h2><p>Story briefs, front matter, context-change history, continuity notes and revision proposals stay with the local book. A drafting session asks once before its described batch of sequential requests, with a request limit you choose. Complete revision requests use up to 60,000 characters per selected chapter; continuity reviews use bounded excerpts. Exported books contain your private manuscript content.</p><h2>Local previews, defaults and sessions</h2><p>Author details, book defaults, appearance and unfinished setup are stored on this device. Voice previews and parsed reference extracts may be reused from a bounded local cache; you can clear it in Settings without deleting your books or saved API connections. Writing sessions store their book, time and net word count locally. Native asset caches contain bundled application files only. API requests and API keys are never put into the service-worker cache. Structured suggestions may use one repair request within the batch described before approval; partial text and completed planning stages are kept for recovery.</p>`},terms:{title:'Terms of service',html:`<p>Effective November 15, 2026. Using BookWiz means accepting these terms and the BookWiz Non-Commercial License 1.0.</p><h2>Your work is yours</h2><p>You retain 100% of your ownership rights in your manuscripts, book titles, characters, cover designs, and other original work. BookWiz claims no ownership and takes no royalty. The software license does not restrict selling or publishing books you create. Third-party models and source materials may have their own terms; you are responsible for checking them.</p><h2>Responsible authorship</h2><p>Use only reference material you have permission to use. Verify factual claims, citations, originality, rights, and suitability before publication. AI can invent facts, repeat existing phrases, or produce biased content. No output is guaranteed to win a prize, be original, be legally publishable, or meet a publisher’s standards.</p><h2>Providers and costs</h2><p>You supply and control your own API accounts. A consumer chatbot subscription may not include API access. Provider pricing, free-tier quotas, availability, and data practices can change. Every AI request may incur a charge directly with your provider. BookWiz does not sell API credit or process payments.</p><h2>Availability and backups</h2><p>The software is provided as is, without warranties of uninterrupted service, fitness, accuracy, or freedom from errors. Keep backups. To the extent permitted by law, the maintainer is not liable for indirect loss, lost manuscripts, provider charges, or third-party service failures. Nothing here limits rights or liabilities that cannot lawfully be excluded.</p><h2>Age and content</h2><p>The intended audience is writers aged 16 and older. This is guidance, not an official store age rating. Minors need any consent required by their jurisdiction and provider. The app has no public feed, direct messaging, or shared user directory. Do not use it for illegal, abusive, or infringing activity.</p><h2>Support, reporting, and blocking</h2><p>Use Help &amp; support to prepare a report and reach the maintainer. You can remove any provider connection to prevent future requests through it, dismiss generated text, or delete a local project. No public user interaction exists to block. Do not publish secrets in a report.</p><h2>Changes and contact</h2><p>Material changes will be dated in these documents. Contact: <a href="https://github.com/muneebwanee" target="_blank" rel="noopener">muneebwanee on GitHub</a>. The software is governed by its accompanying license.</p><h2>Editorial review and publication</h2><p>You decide which generated plans, passages and revisions to accept. Word counts and voice adherence are approximate. Continuity notes and publishing checks assist review; they do not certify accuracy, originality, rights, or printer compliance. Literary polish makes no AI-detection or human-authorship claim. Author influence settings request original prose using broad craft characteristics. You remain responsible for your final text, rights, production files and publication disclosures.</p>`},license:{title:'BookWiz Non-Commercial License',html:`<p>BWNCL 1.0 · Copyright © 2026 muneebwanee. All rights reserved except as granted below.</p><h2>Permissions</h2><p>You may inspect and study the source, run BookWiz privately for personal non-commercial use, and make private modifications. You may submit patches and contributions to the official BookWiz repository designated by muneebwanee. You may share the minimum source excerpts necessary for a contribution or a good-faith security report.</p><p>You may create a GitHub fork of github.com/muneebwanee/BookWizOfficial for study and non-commercial upstream contributions. Retain copyright, license and third-party notices, and identify the official project. This permission does not extend to unofficial packaged releases, commercial hosting, resale or rebranding.</p><h2>Restrictions</h2><p>Except for the GitHub contribution forks permitted above, you may not distribute, mirror, sublicense, or publish standalone copies of BookWiz or modified versions, including source or packaged builds, without prior written permission from muneebwanee. You may not sell, rent, license for payment, rebrand for resale, host as a commercial service, bundle for commercial gain, or commercially exploit the software. Attribution does not waive these restrictions. You may not imply endorsement or remove copyright and license notices.</p><h2>Your books are excluded</h2><p>This license governs the software, not works created with it. You retain 100% of your rights in your written works and may publish, sell, license, and distribute them commercially. BookWiz claims no royalty or ownership in your output. Third-party content and model terms remain separate.</p><h2>Contributions</h2><p>By submitting an upstream contribution, you confirm you have the right to do so and grant muneebwanee a perpetual, worldwide, non-exclusive, royalty-free right to use, modify, reproduce, and distribute that contribution as part of official BookWiz releases. You retain copyright in your contribution.</p><h2>Third-party components</h2><p>Third-party libraries, fonts, and tools retain their own licenses. BWNCL does not narrow their independent permissions. See THIRD_PARTY_NOTICES in the source distribution.</p><h2>Termination and disclaimer</h2><p>Permissions terminate upon breach. Stop using and remove unauthorized copies. The software is provided AS IS, without warranty of any kind, to the maximum extent permitted by law. The author is not liable for claims or damages arising from use. No trademark right or patent license is granted. If any clause is unenforceable, the remaining clauses continue to apply.</p><p>For additional permissions, contact <a href="https://github.com/muneebwanee" target="_blank" rel="noopener">github.com/muneebwanee</a>. This is a source-available license and is not an OSI-approved open-source license.</p>`}};
function legal(){return `<div class="page"><div class="page-intro"><div><h1>Trust, in plain words.</h1><p>Your rights, your privacy, and the principles behind BookWiz.</p></div><div class="row gap8">${B('copy-legal','Copy','file','secondary')}${B('print-legal','Print','download','secondary')}</div></div><div class="row between wrap"><nav class="legal-nav">${Object.entries(legalDocs).map(([v,d])=>`<button data-action="legal-tab" data-value="${v}" class="${legalTab===v?'active':''}">${v==='license'?'BWNCL 1.0':d.title}</button>`).join('')}</nav><label class="search">${I('search')}<input id="legal-search" type="search" aria-label="Search this document"></label></div><article class="legal" id="legal-document"><h2>${legalDocs[legalTab].title}</h2>${legalDocs[legalTab].html}</article><footer class="library-footer"><span>BookWiz by <a href="https://github.com/muneebwanee" target="_blank" rel="noopener">muneebwanee</a></span><span>Your words. Your ownership. Always.</span></footer></div>`;}
function modal(title,body,actions='',{returnToWriting=true}={}){if(compileSession&&!body.includes('id="compiler-state"')){compileSession.controller.abort();if(compileSession.native)window.BookWizHost?.cancelLaTeX?.();compileSession=null;}captureWritingAnchor();if(returnToWriting&&writingAnchor&&state.projects.some(p=>p.id===writingAnchor.bookId)&&!actions.includes('data-action="back-to-writing"'))actions=B('back-to-writing','Back to writing','pen','quiet')+actions;dialog.className='';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${I('close')}</button></div><div class="dialog-body">${body}<div id="dialog-error" class="error" role="alert"></div></div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!dialog.open)dialog.showModal();dialog.querySelector('.dialog-body').scrollTop=0;}
function confirmDialog(title,text,onYes,label='Continue',danger=false){modal(title,`<p>${text}</p>`,B('close-dialog','Cancel','','secondary')+B('confirm-yes',label,'',danger?'danger':'primary'));dialog.querySelector('[data-action="confirm-yes"]').onclick=()=>{dialog.close();try{Promise.resolve(onYes()).catch(reportError);}catch(error){reportError(error);}};}
function providerSetup(id='gemini',connectionId=null){const saved=state.connections.find(c=>c.id===connectionId),p=providers.find(p=>p.id===id);if(p.protocol==='native'&&!deviceCapabilities().apple){openAppFeature('apple');return;}if(p.protocol==='native'){modal('Apple Intelligence',`<p>${esc(p.note)}</p><ol class="setup-steps"><li>Enable Apple Intelligence in your device Settings and finish downloading its models.</li><li>Choose a supported language and check <a href="${p.url}" target="_blank" rel="noopener">device availability</a>.</li><li>Save this connection, then choose Verify to try a short request.</li></ol><form id="connection-form" data-provider="${p.id}" ${saved?`data-connection="${saved.id}"`:''}><label class="field"><span>Connection name</span><input name="name" value="${esc(saved?.name||p.name)}" required maxlength="60"></label><input type="hidden" name="model" value="apple-device"><input type="hidden" name="endpoint" value="${p.endpoint}"><input type="hidden" name="replyLimit" value="4096"></form>`,B('close-dialog','Cancel')+B('save-connection','Save connection','check','primary'));return;}modal(`Connect ${p.name}`,`<span class="badge">${p.tag}</span><p style="margin-top:14px">${p.note}</p><ol class="setup-steps"><li><div><a href="${p.url}" target="_blank" rel="noopener">Open the official ${p.local?'setup guide':'key dashboard'} ${I('external')}</a>.<br>${p.local?'Install your runtime and load a compatible model.':'Create an account, then create an API key with the required permissions.'}</div></li><li><div>Review <a href="${p.pricing}" target="_blank" rel="noopener">current ${p.local?'model documentation':'pricing & quotas'}</a>. ${p.local?'Start its local API server.':'Set a spending limit where your provider offers one.'}</div></li><li><div>Add the details below. Verify with a short test before sharing a manuscript.</div></li></ol><form id="connection-form" data-provider="${p.id}" ${saved?`data-connection="${saved.id}"`:''}><label class="field"><span>Connection name</span><input name="name" value="${esc(saved?.name||p.name)}" required maxlength="60"></label><label class="field"><span>API key ${p.local?'· optional for local models':''}</span><input name="key" type="password" autocomplete="off" ${p.local||saved?'':'required'}>${saved?'<small>Leave blank to keep the current key or encrypted vault.</small>':''}</label><label class="field"><span>Model ID</span><input name="model" value="${esc(saved?.model||p.model)}" required></label><label class="field"><span>Endpoint base URL</span><input name="endpoint" type="url" value="${esc(saved?.endpoint||p.endpoint)}" required></label><label class="field"><span>Maximum reply length · tokens</span><input name="replyLimit" type="number" min="512" max="32768" step="256" value="${saved?.replyLimit||4096}" required><small>Planning uses small saved steps. Longer replies depend on your model’s limits.</small></label><label class="field"><span>Vault passphrase · optional</span><input name="passphrase" type="password" autocomplete="new-password" minlength="10"><small>Leave blank to keep your key only for this session. Add at least 10 characters to save an encrypted key on this device. The passphrase is never saved.</small></label><button type="submit" hidden></button></form>`,B('close-dialog','Cancel')+B('save-connection','Save connection','lock','primary'));}
async function getKey(c){if(sessionKeys.has(c.id))return sessionKeys.get(c.id);if(providerFor(c).local&&!c.vault)return '';if(!c.vault){providerSetup(c.provider);throw Error('Add your session key again, or save it in the encrypted vault.');}return new Promise((resolve,reject)=>{let done=false;modal('Unlock this connection',`<p>Enter the vault passphrase for ${esc(c.name)}. Your passphrase stays on this device and is not sent to the provider.</p><label class="field"><span>Vault passphrase</span><input id="vault-password" type="password" autocomplete="current-password"></label>`,B('close-dialog','Cancel')+B('unlock-key','Unlock','lock','primary'));dialog.querySelector('[data-action="unlock-key"]').onclick=async()=>{try{const key=await decryptKey(c.vault,dialog.querySelector('#vault-password').value);sessionKeys.set(c.id,key);done=true;dialog.close();resolve(key);}catch{dialog.querySelector('#dialog-error').textContent='That passphrase could not unlock this connection. Try again.';}};dialog.addEventListener('close',()=>{if(!done)reject(Error('Connection remains locked.'));},{once:true});});}
async function consent(c,description){return new Promise(resolve=>{let accepted=false;modal(providerFor(c).protocol==='native'?'Use this device’s model?':'Share with your AI provider?',providerFor(c).protocol==='native'?`<p>Your device will process ${esc(description)}. Your words stay on this device. Apple Intelligence must be available for your device, language and region.</p>`:`<p><strong>${esc(c.name)}</strong> will receive ${esc(description)}. The request goes directly to <strong>${esc(new URL(c.endpoint).hostname)}</strong>.</p><div class="notice warning" style="margin-top:17px">Your provider’s data policy and usage charges apply. Free-tier quotas may be limited. BookWiz does not retain a server copy.</div>`,B('close-dialog','Keep private')+B('approve-ai','Share & continue','arrow','primary'));dialog.querySelector('[data-action="approve-ai"]').onclick=()=>{accepted=true;dialog.close();};dialog.addEventListener('close',()=>resolve(accepted),{once:true});});}
function context(p){return storyContext(p); }
function parseJSON(text){return JSON.parse(text.replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,'').trim());}
function editEntity(type='characters',index=-1,initial=null){if(!entityFields[type])return;const p=project();if(!p)return;p[type]??=[];const before=index>=0?p[type][index]:null;entityCompose={p,type,index,before:before?structuredClone(before):null,draft:initial||structuredClone(before)||(type==='bible'&&p.worlds?.some(w=>w.id===worldFilter)?{worldId:worldFilter}:{}),suggested:false};renderEntityForm();}
function renderEntityForm(){const c=entityCompose;if(!c||!state.projects.includes(c.p))return;const {p,type,index,draft:e}=c,chars=type==='characters',label=chars?'character':type==='worlds'?'world':'world detail',matches=referencedChapters(p,c.before),drafted=p.chapters.filter(ch=>plain(ch.text).trim()).length;modal(index<0?'Add a '+label:'Edit '+label,`<form id="entity-form" data-type="${type}" data-index="${index}" class="stack">${c.suggested?'<p class="entity-suggested" role="status">A suggested direction. Edit it freely, then save when it belongs.</p>':''}<label class="field"><span>Name</span><input name="name" required value="${esc(e.name||'')}" maxlength="100"></label>${chars?`<label class="field"><span>Role</span><input name="role" value="${esc(e.role||'')}" maxlength="100"></label>`:type==='bible'?`<label class="field"><span>Kind of detail</span><select name="type">${opts(worldKinds,e.type)}</select></label>`:''}${type!=='worlds'&&p.worlds?.length?`<label class="field"><span>World</span><select name="worldId"><option value="">Shared story</option>${p.worlds.map(w=>`<option value="${esc(w.id)}" ${e.worldId===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label>`:''}${entityFields[type].map(([k,l])=>`<label class="field"><span>${l}</span><textarea name="${k}" rows="3" maxlength="4000">${esc(e[k]||'')}</textarea></label>`).join('')}<div class="entity-ai-tools"><label class="field"><span>Direction for your co-author · optional</span><textarea name="direction" rows="2" maxlength="2000">${esc(e.direction||'')}</textarea></label><div class="row wrap gap8">${B('suggest-entity',index>=0?'Explore another direction':'Suggest a profile','pen','secondary','type="button"')}${B('refine-entity-draft','Refine these details','feather','quiet','type="button"')}</div></div>${drafted?`<p class="entity-impact">Saving updates the story guide immediately and flags ${drafted} drafted ${drafted===1?'chapter':'chapters'} for continuity review.${matches.length?' Mentioned in: '+matches.map(m=>esc(m.title)).join(', ')+'.':''}</p>`:''}</form>`,(index>=0?B('delete-entity','Delete','','danger',`data-value="${type}" data-index="${index}"`):'')+B('close-dialog','Cancel')+B('save-entity','Save','check','primary'));dialog.classList.add('entity-dialog');}
async function suggestEntity(refine=false){const c=entityCompose,form=document.querySelector('#entity-form');if(!c||!form)return;const draft=Object.fromEntries(new FormData(form));c.draft=draft;if(!isTextModel(activeConnection()))throw Error('Choose a text model in AI & model hub before asking for a suggestion. Your fields are unchanged.');try{const data=await aiJSON(`${storyContext(c.p)}\n${entityPrompt(c.p,c.type,draft,draft.direction,refine)}`,'your premise, story guide, current profile, direction and reference excerpts',undefined,2400);if(!state.projects.includes(c.p))return;if(!data){if(entityCompose===c)renderEntityForm();return;}const suggestion=normalizeEntity(data,c.type);if(entityCompose!==c){c.p.notes.unshift({id:uid(),date:Date.now(),text:'Suggested story profile — not applied.\n'+JSON.stringify(suggestion,null,2)});save();return;}c.draft={...draft,...suggestion,worldId:draft.worldId||''};c.suggested=true;renderEntityForm();}catch(error){if(entityCompose===c)renderEntityForm();throw error;}}
function saveStoryEntity(form){const c=entityCompose;if(!c||!state.projects.includes(c.p))throw Error('Open the profile again before saving.');const {p,type,index,before}=c;if(index>=0&&JSON.stringify(p[type][index])!==JSON.stringify(before))throw Error('This profile changed while you were editing. Reopen it to keep the latest version.');const normalized=normalizeEntity(Object.fromEntries(new FormData(form)),type),data={...before,...normalized};if(before&&Object.keys(normalized).every(k=>String(before[k]||'')===String(normalized[k]||''))){dialog.close();toast('Your profile is already saved.');return;}if(type==='worlds')data.id=before?.id||uid();if(type!=='worlds'&&data.worldId&&!p.worlds.some(w=>w.id===data.worldId))data.worldId='';const apply=()=>{if(index<0)p[type].push(data);else p[type][index]=data;const n=registerContextChange(p,type,entityChange(type,before,data));entityCompose=null;save();dialog.close();render();toast(n?'Story guide updated. '+n+' drafted chapter(s) need review.':'Story detail saved.');};if(p.chapters.some(ch=>plain(ch.text).trim()))confirmDialog('Update the story context?','New writing will use this profile. Existing chapters will be marked for continuity review; you choose which revisions to accept.',apply,'Update story');else apply();}
function chapterKey(p=project(),c=p?.chapters[chapterIndex]){return p&&c?p.id+':'+c.id:'';}
function captureWritingAnchor(){const editor=document.querySelector('#editor');if(!editor)return;const p=state.projects.find(p=>p.id===editor.dataset.book),c=p?.chapters.find(c=>c.id===editor.dataset.chapter);if(!c)return;writingAnchor={bookId:p.id,chapterId:c.id,scroll:document.querySelector('#main')?.scrollTop||0};}
function pageLocation(){return {route,activeId,chapterIndex,studioTab,settingTab,hubTab,legalTab};}
function workspaceNavigation(){const p=state.projects.find(p=>p.id===writingAnchor?.bookId);if(!p)return '';const writing=route==='studio'&&studioTab==='draft'&&p.id===activeId&&p.chapters[chapterIndex]?.id===writingAnchor.chapterId;return `<nav class="workspace-navigation" aria-label="Workspace history"><div class="history-buttons"><button type="button" class="icon-btn" data-action="workspace-back" aria-label="Go back" ${!pageTrail.canBack?'disabled':''}>${I('back')}</button><button type="button" class="icon-btn" data-action="workspace-forward" aria-label="Go forward" ${!pageTrail.canForward?'disabled':''}>${I('arrow')}</button></div>${writing?`<span class="writing-location">${esc(p.chapters[chapterIndex].title)}</span>`:B('back-to-writing','Back to writing','pen','quiet')}</nav>`;}
function navigateTrail(delta){narrationDialogEpoch++;const main=document.querySelector('#main');pageTrail.remember(main?.dataset.trail,main?.scrollTop||0);let entry=pageTrail.move(delta);if(!entry)return;const v=entry.snapshot;if(v.route==='wizard'&&!wizard){toast('This setup is no longer open. Start a new book from your library.');pageTrail.move(-delta);return;}if(['studio','reader','covers'].includes(v.route)&&!state.projects.some(p=>p.id===v.activeId)){toast('This book is no longer in your library.');pageTrail.move(-delta);return;}if(route==='wizard'&&wizard)syncWizard();({route,activeId,chapterIndex,studioTab,settingTab,hubTab,legalTab}=v);drawer=null;menuOpen=false;document.body.classList.remove('zen');pendingPageScroll=entry.scroll;render();return true;}
function returnToWriting(){entityCompose=null;narrationDialogEpoch++;const anchor=writingAnchor,p=state.projects.find(p=>p.id===anchor?.bookId);if(!p)return;const index=p.chapters.findIndex(c=>c.id===anchor.chapterId);if(index<0)return;if(route==='wizard'&&wizard)syncWizard();if(dialog.open)dialog.close();activeId=p.id;chapterIndex=index;studioTab='draft';route='studio';menuOpen=false;drawer=null;document.body.classList.remove('zen');pendingPageScroll=anchor.scroll;render();document.querySelector('#editor')?.focus({preventScroll:true});}
function updateDraftButtons(){const key=chapterKey();document.querySelectorAll('[data-action="undo-draft"]').forEach(b=>b.disabled=!draftHistory.canUndo(key));document.querySelectorAll('[data-action="redo-draft"]').forEach(b=>b.disabled=!draftHistory.canRedo(key));}
function moveDraftHistory(delta){const titleFocused=document.activeElement?.id==='chapter-title',p=project(),c=p?.chapters[chapterIndex];if(!c)return;draftHistory.sync(chapterKey(),c);const next=draftHistory.move(chapterKey(),delta);if(!next)return;addRevision(p,c,delta<0?'Before undo':'Before redo');Object.assign(c,next);c.status='Drafting';p.updated=Date.now();if(p.continuityReview)p.continuityReview.stale=true;const affected=p.chapters.slice(chapterIndex+1).some(c=>plain(c.text).trim());if(affected)registerContextChange(p,'manuscript revision','Chapter '+(chapterIndex+1)+' was '+(delta<0?'restored with Undo.':'restored with Redo.'),{fromIndex:chapterIndex+1});save();render();const field=document.querySelector(titleFocused?'#chapter-title':'#editor');field?.focus({preventScroll:true});if(titleFocused)field?.setSelectionRange(field.value.length,field.value.length);}
function toggleFocus(){const active=document.body.classList.toggle('zen');const button=document.querySelector('.exit-zen');if(active)button?.focus({preventScroll:true});else document.querySelector('[data-action="zen"]')?.focus({preventScroll:true});}
function speechPreferences(){return {engine:'device',voice:'',cloudVoice:'marin',rate:1,...state.settings.speech};}
const narrator=new Narrator({onState:updateNarrationUI});
let narrationVoices=[],narrationBook=null,narrationDialogEpoch=0;
function updateNarrationUI(status){const el=document.querySelector('#narration-status');if(!el)return;el.textContent=status.message||({idle:'Ready to read.',loading:'Preparing narration…',playing:`Reading passage ${status.index+1} of ${status.total}.`,paused:'Reading paused.',error:'Choose another voice and try again.'})[status.state];const pause=document.querySelector('[data-action="pause-narration"]'),start=document.querySelector('[data-action="start-narration"]');if(pause){pause.disabled=!['playing','paused'].includes(status.state);pause.dataset.action=status.state==='paused'?'resume-narration':'pause-narration';pause.innerHTML=I(status.state==='paused'?'play':'pause')+(status.state==='paused'?'Resume':'Pause');}const resume=document.querySelector('[data-action="resume-narration"]');if(resume&&status.state!=='paused'){resume.dataset.action='pause-narration';resume.innerHTML=I('pause')+'Pause';resume.disabled=status.state!=='playing';}if(start)start.disabled=['loading','playing','paused'].includes(status.state);}
async function openNarration(){const epoch=++narrationDialogEpoch,p=project(),c=p?.chapters[chapterIndex];if(!c)return;if(narrationBook?.p!==p||narrationBook?.chapter!==c)narrator.stop();narrationBook={p,chapter:c};narrator.host=window.BookWizHost;narrationVoices=rankedVoices(await deviceVoices(),localeOf(p).code);if(epoch===narrationDialogEpoch&&state.projects.includes(p))renderNarrationForm();}
function renderNarrationForm(){const prefs=speechPreferences(),connections=state.connections.filter(c=>c.provider==='openai'),cloud=prefs.engine==='cloud';modal('Listen to your pages',`<form id="narration-form" class="stack"><div class="form-grid"><label class="field"><span>Narration</span><select name="engine"><option value="device" ${!cloud?'selected':''}>Device voices</option><option value="cloud" ${cloud?'selected':''}>Studio voices · OpenAI</option></select></label><label class="field"><span>Reading speed</span><select name="rate">${[.75,.85,1,1.1,1.25,1.5].map(n=>`<option value="${n}" ${Number(prefs.rate)===n?'selected':''}>${n}×${n===1?' · Natural pace':''}</option>`).join('')}</select></label></div>${cloud?`<label class="field"><span>Voice</span><select name="cloudVoice">${studioVoices.map(v=>`<option value="${v}" ${prefs.cloudVoice===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label class="field"><span>OpenAI connection</span><select name="connection">${connections.map(c=>`<option value="${c.id}" ${prefs.connection===c.id?'selected':''}>${esc(c.name)}</option>`).join('')||'<option value="">Connect an OpenAI API key first</option>'}</select></label><p class="small muted">Studio voices are AI-generated. The selected chapter is sent to OpenAI in short passages after you approve. OpenAI API charges apply; a ChatGPT subscription does not include API credit.</p>${!connections.length?B('connect-speech','Connect OpenAI','cpu','secondary','type="button"'):''}`:`<label class="field"><span>Voice</span><select name="voice">${narrationVoices.map((v,i)=>`<option value="${esc(v.voiceURI||v.id)}" ${prefs.voice===(v.voiceURI||v.id)||!prefs.voice&&i===0?'selected':''}>${esc(v.name)} · ${esc(v.lang)}${v.quality?' · '+esc(v.quality):''}${v.localService===false?' · Online':' · On device'}</option>`).join('')||'<option value="">No device voices available</option>'}</select></label><p class="small muted">Enhanced voices can be downloaded in your device’s speech settings. Voice quality and languages depend on the installed speech engine. Online voices may send text to that service.</p><details class="voice-install-guide"><summary>Add more device voices</summary><ol><li>On iPhone or iPad, open Settings → Accessibility → Read & Speak → Voices. Select a language and download an enhanced or premium voice where offered.</li><li>On Android, open your text-to-speech output settings. Choose the speech engine and install its voice data. Menu names vary by device.</li><li>On desktop, install speech voices in your system’s language or accessibility settings. Reopen this voice chooser after installation.</li></ol></details>`}<p class="narration-chapter">${esc(narrationBook?.chapter.title||'')}</p><p id="narration-status" role="status" aria-live="polite">Ready to read.</p><div class="row wrap gap8">${B('preview-narration','Try a passage','volume','secondary','type="button"')}${B('pause-narration','Pause','pause','quiet','type="button" disabled')}${B('stop-narration','Stop','stop','quiet','type="button"')}</div></form>`,B('close-dialog','Close')+B('start-narration','Read chapter','play','primary'));dialog.classList.add('narration-dialog');updateNarrationUI({state:narrator.state,index:narrator.index,total:narrator.chunks?.length||0});}
function saveSpeechForm(){const form=document.querySelector('#narration-form');if(form)state.settings.speech={...speechPreferences(),...Object.fromEntries(new FormData(form))};save();return speechPreferences();}
async function startNarration(preview=false){const epoch=narrationDialogEpoch,prefs=saveSpeechForm(),source=narrationBook;if(!source)return;narrator.stop();const text=plain(source.chapter.text).trim();if(!text)throw Error('Write a passage before reading aloud.');const input=preview?text.slice(0,240):text;let cloud;
 if(prefs.engine==='cloud'){const c=state.connections.find(c=>c.id===prefs.connection&&c.provider==='openai');if(!c)throw Error('Connect an OpenAI API key for Studio voices, or choose Device voices.');const key=await getKey(c);if(epoch!==narrationDialogEpoch)return;if(!await consent(c,`the ${preview?'sample passage':'selected chapter'} for AI-generated speech in up to ${speechChunks(input).length} audio requests. OpenAI speech usage charges apply`)){if(epoch===narrationDialogEpoch)renderNarrationForm();return;}if(epoch!==narrationDialogEpoch)return;cloud=(chunk,signal)=>openAISpeech(c,key,chunk,prefs.cloudVoice,{signal});}
 else{const voice=narrationVoices.find(v=>(v.voiceURI||v.id)===prefs.voice);if(!voice)throw Error('Choose an available device voice, or select Studio narration.');if(voice.localService===false){const approved=await new Promise(resolve=>{let yes=false;confirmDialog('Use this online voice?','This voice may send the selected text to your device’s speech provider. Its data policy applies.',()=>{yes=true;resolve(true);},'Read aloud');dialog.addEventListener('close',()=>setTimeout(()=>{if(!yes)resolve(false);},0),{once:true});});if(!approved){if(epoch===narrationDialogEpoch)renderNarrationForm();return;}}}
 if(epoch!==narrationDialogEpoch)return;renderNarrationForm();narrator.start(input,{engine:prefs.engine==='cloud'?'cloud':'device',voice:prefs.voice,rate:Number(prefs.rate)||1,lang:localeOf(source.p).code,cloud}).catch(reportError);}

function deleteStoryEntity(el){const p=project(),type=el.dataset.value,index=Number(el.dataset.index),item=p?.[type]?.[index];if(!item)return;confirmDialog('Remove this story detail?',type==='worlds'?'The world is removed from the guide. Its character and world-detail notes will move to Shared story. Existing chapters will need a continuity review.':'This removes the profile from the guide. Your manuscript stays as written and will be flagged for continuity review.',()=>{if(!state.projects.includes(p))return;p[type].splice(index,1);if(type==='worlds')for(const x of [...p.characters,...p.bible])if(x.worldId===item.id)x.worldId='';registerContextChange(p,type,'Removed '+item.name+' from the story guide.');save();render();},'Remove',true);}
function quickNote(){const p=project(),inbox=[...(state.captureInbox||[]),...(state.watchInbox||[]).map(n=>({...n,watch:true}))];modal('Catch a passing thought',`<p>${p?'A note for <strong>'+esc(p.title)+'</strong>.':'Keep a thought here until it has a book to belong to.'}</p><label class="field"><span>Your thought</span><textarea id="quick-note-text" rows="6" maxlength="20000" autofocus></textarea></label>${inbox.length?'<h3>Unassigned thoughts</h3>'+inbox.map(n=>`<article class="setting-details"><p>${esc(n.text)}</p>${p?B('adopt-capture','Keep in this book','book','quiet',`data-id="${esc(n.id)}" data-source="${n.watch?'watch':'capture'}"`):''}</article>`).join(''):''}`,B('close-dialog','Cancel')+B('save-note','Keep this thought','note','primary'));}
async function sendChat(text){const p=project();if(!p)return;const conversation=chat,replyRole='The Red Pen';chatSessions.set(p.id,conversation);const out=await ai(`${context(p)}\nCURRENT CHAPTER: ${plain(p.chapters[chapterIndex]?.text||'').slice(-16000)}\nRECENT CONVERSATION: ${conversation.slice(-6).map(m=>m.role+': '+m.text).join('\n').slice(-8000)}\nEDITORIAL APPROACH: ${redPenMode==='critique'?'Give a rigorous literary close reading. Scores are editorial opinions. Use only exact quotes from the supplied text.':'Act as a thoughtful co-author. Offer specific options that preserve the writer’s voice, context and agency.'}\nWRITER: ${text}`, 'your question, recent co-author conversation, current chapter, premise, references, and story notes',undefined,3000);if(!out||!state.projects.some(x=>x.id===p.id))return;conversation.push({role:'You',text},{role:replyRole,text:out});if(activeId===p.id){render();document.querySelector('#chat-messages')?.scrollTo(0,999999);}else toast('Your co-author response is ready in '+p.title+'.');}
function importBackupText(text){if(typeof text!=='string'||text.length>30*1024*1024)throw Error('Choose a backup smaller than 30 MB.');let data;try{data=validateBackup(JSON.parse(text));}catch(error){if(error.name==='SyntaxError')throw Error('Choose a BookWiz JSON backup. This file could not be read.');throw error;}confirmDialog('Import this backup?',`${data.projects.length} book(s) and ${data.captureInbox?.length||0} unassigned thought(s) will be added as independent copies. Existing books and settings stay as they are.`,()=>{let firstImported=null;for(const p of data.projects){const q=structuredClone(p);q.id=uid();q.chapters=q.chapters.map(c=>({...c,id:c.id||uid(),text:cleanHTML(c.text)}));q.revisions=Array.isArray(q.revisions)?q.revisions.filter(r=>r&&typeof r.text==='string'&&typeof r.title==='string'):[];q.lastChapter=Math.max(0,Math.min(Number(q.lastChapter)||0,q.chapters.length-1));q.characters=Array.isArray(q.characters)?q.characters:[];q.bible=Array.isArray(q.bible)?q.bible:[];q.worlds=Array.isArray(q.worlds)?q.worlds:[];q.references=Array.isArray(q.references)?q.references:[];q.notes=Array.isArray(q.notes)?q.notes:[];q.trim=trims[q.trim]||q.trim==='Custom'?q.trim:'Trade paperback';q.target=Number(q.target)||65000;q.updated=Date.now();if(q.image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(q.image))delete q.image;q.premise=String(q.premise||'');q.author=String(q.author||state.settings.name);state.projects.push(q);if(!firstImported)firstImported=q.id;}if(data.captureInbox?.length){state.captureInbox??=[];state.captureInbox.push(...data.captureInbox.map(n=>({id:uid(),text:n.text,date:Number(n.date)||Date.now()})));}if(firstImported){activeId=firstImported;state.settings.lastProject=firstImported;}route='library';save();render();toast('Your books and thoughts are safely imported.');},'Import books');}
function safeBackup(){return {...state,connections:state.connections.map(({vault,...c})=>c)};}
function localModelsHTML(){
 const checking=localModelState.phase==='checking',models=localModelState.models;
 return `<section class="panel local-discovery" id="local-model-discovery" aria-labelledby="local-model-heading"><div class="local-discovery-heading">${motionGraphic('scan',checking?'loading-vector':'service-vector')}<div class="grow"><span class="section-eyebrow">ON THIS DEVICE</span><h2 id="local-model-heading">${checking?'Finding your local models':models.length?models.length+' local '+(models.length===1?'model is':'models are')+' ready':'Intelligence, close to home'}</h2><p>${checking?'Reading runtime model lists. No manuscript is shared.':models.length?'Detected automatically. Choose a model without entering its address.':'Ollama, LM Studio and llama.cpp appear here when their local server is running.'}</p></div>${B('scan-local-models',checking?'Checking…':'Check again','refresh','secondary',checking?'disabled aria-busy="true"':'')}</div>${models.length?`<div class="detected-models">${models.map(model=>`<div class="detected-model"><span class="service-dot" aria-hidden="true"></span><div class="grow"><strong>${esc(model.native?model.runtime:model.model)}</strong><small>${esc(model.runtime)} · on this device</small></div>${B('use-detected-model','Use model','arrow','primary',`data-provider="${esc(model.provider)}" data-model="${esc(model.model)}" data-endpoint="${esc(model.endpoint)}"`)}</div>`).join('')}</div>`:localModelState.phase==='done'?'<p class="service-note">No runtime responded. Start a model server on this device, then check again. Your browser may request local-network access.</p>':''}</section>`;
}
async function scanLocalModels(){
 if(localModelTask)return localModelTask;
 localModelState.phase='checking';lastLocalCheck=Date.now();
 const refresh=()=>{const panel=document.querySelector('#local-model-discovery');if(panel)panel.outerHTML=localModelsHTML();};refresh();
 localModelTask=(async()=>{try{localModelState.models=await discoverLocalModels();}catch{localModelState.models=[];}finally{localModelState.phase='done';lastLocalCheck=Date.now();localModelTask=null;refresh();}})();
 return localModelTask;
}
function useDetectedModel(data){
 const found=localModelState.models.find(model=>model.provider===data.dataset.provider&&model.model===data.dataset.model&&model.endpoint===data.dataset.endpoint);if(!found)return;
 let connection=state.connections.find(item=>item.provider===found.provider&&item.model===found.model&&item.endpoint===found.endpoint);
 if(!connection){connection={id:uid(),provider:found.provider,name:found.runtime+' · '+found.model,model:found.model,endpoint:found.endpoint,replyLimit:4096,...(found.localRelay?{localRelay:found.localRelay}:{}),detected:Date.now()};state.connections.push(connection);sessionKeys.set(connection.id,'');}
 if(found.localRelay)connection.localRelay=found.localRelay;
 state.activeConnection=connection.id;save();if(wizardIntent&&isTextModel(connection))openStoryWizard();else render();toast((found.native?found.runtime:found.model)+' is selected. Requests still ask before sharing.');
}
async function compileTex(){
 if(!project()){toast('Choose a book to typeset.');return;}
 compilerConnection=null;
 const caps=deviceCapabilities();
 if(['android','ios'].includes(caps.platform)&&caps.pdf){
  const [width,height]=trimOf(project());
  modal('Make a PDF',`<div class="native-pdf-summary">${I('book')}<div><span class="section-eyebrow">NATIVE PDF</span><h3>Your book, at its proper size.</h3><p>${width} × ${height} inches · ${esc(project().publicationStyle||'Modern literary')}</p></div></div><p>Open your device’s print sheet, then choose <strong>Save as PDF</strong> or a printer. BookWiz supplies the book’s page size, type and margins.</p><p class="small muted">If a printer changes the paper size, use the book’s trim size and 100% scale for the closest match to the proof.</p><details class="setting-details"><summary>LaTeX typesetting</summary><p>For XeLaTeX or Tectonic typesetting, export the complete source and open it on a computer with a TeX engine. This phone’s native PDF engine is ready without a local compiler service.</p>${B('export-tex','Download LaTeX source','download','secondary')}</details>`,B('preview-book','Read the proof','book','secondary')+B('print-book','Save / print PDF','file','primary'),{returnToWriting:false});
  dialog.classList.add('native-pdf-dialog');return;
 }
 modal('Typeset your book',`<div id="compiler-state" class="compiler-state" role="status" aria-live="polite"></div><p class="compiler-privacy">${I('shield')} Typesetting stays on this device. Your manuscript is not sent to a cloud compiler.</p><details class="setting-details"><summary>Compiler connection</summary><label class="field"><span>Local service address</span><input id="latex-endpoint" type="url" value="${esc(state.settings.latexEndpoint||'http://localhost:4317/compile')}"></label><p class="small muted">Desktop editions detect installed TeX engines directly. For the browser edition, run <code>npm run compiler</code> from the source folder. It also serves a local studio at <code>http://localhost:4317</code>.</p><p class="small muted">TeX Live, MacTeX, MiKTeX and Tectonic are supported. Use <strong>Connect this studio</strong> when the local compiler asks to allow this address.</p></details>`,B('close-dialog','Close')+B('export-tex','LaTeX source','download','quiet')+B('print-book','Print / PDF','file','secondary')+B('check-compiler','Check again','refresh','secondary')+B('run-compile','Compile PDF','book','primary','disabled'));
 await refreshCompiler();
}
async function refreshCompiler(){
 const id=++compilerCheck,area=document.querySelector('#compiler-state'),button=dialog.querySelector('[data-action="run-compile"]'),check=dialog.querySelector('[data-action="check-compiler"]');if(!area||!button)return;if(check)check.disabled=true;
 button.disabled=true;button.setAttribute('aria-busy','true');
 area.innerHTML=loadingHTML('Finding your typesetter','Checking the compiler and its installed TeX engine.',{kind:'typeset'});
 const value=document.querySelector('#latex-endpoint')?.value.trim();
 try{
  const connection=await discoverCompiler({endpoint:value});
  if(id!==compilerCheck||!document.querySelector('#compiler-state'))return;
  compilerConnection=connection;
  const allowed=connection.originAllowed!==false,ready=connection.available&&allowed;
  const pairing=connection.endpoint?new URL('/connect',connection.endpoint):null;if(pairing)pairing.searchParams.set('origin',location.origin);
  button.disabled=!ready;
  area.innerHTML=`<div class="compiler-summary ${ready?'is-ready':''}">${motionGraphic('typeset','service-vector')}<div><span class="section-eyebrow">${ready?'READY TO TYPESET':'LOCAL COMPILER'}</span><h3>${ready?esc(connection.engine)+' is ready':connection.available?'Allow this studio address':'A typesetter for your pages'}</h3><p>${!allowed?'The compiler is running. Connect this studio once, then return here to typeset your book.':esc(connection.message||'No local compiler is ready.')}</p>${!allowed&&pairing?`<a class="btn secondary" href="${esc(pairing.href)}" target="_blank" rel="noopener">Connect this studio ${I('external')}</a>`:''}</div>${ready?'<span class="status-tag">'+I('check')+' Detected</span>':''}</div>`;
  if(connection.endpoint&&ready){state.settings.latexEndpoint=connection.endpoint;save();}
 }catch(error){area.innerHTML=`<p class="error">${esc(error.message)}</p>`;}
 finally{if(id===compilerCheck){button.removeAttribute('aria-busy');if(check?.isConnected)check.disabled=false;}}
}
async function runCompile(){
 const p=project();if(!p)return;
 if(!compilerConnection?.available||compilerConnection.originAllowed===false)throw Error('Connect a local compiler before typesetting.');
 const button=dialog.querySelector('[data-action="run-compile"]'),area=document.querySelector('#compiler-state');if(!button||button.disabled)return;
 const snapshot=structuredClone(p),connection=compilerConnection,controller=new AbortController(),started=Date.now();compileSession={controller,native:connection.native};
 const peers=[...dialog.querySelectorAll('[data-action="check-compiler"],[data-action="export-tex"],[data-action="print-book"]')];peers.forEach(peer=>peer.disabled=true);
 const cancel=()=>{controller.abort();if(connection.native)window.BookWizHost?.cancelLaTeX?.();};dialog.addEventListener('close',cancel,{once:true});
 const deadline=setTimeout(()=>controller.abort(new DOMException('The compiler took too long.','TimeoutError')),115000);
 const clock=setInterval(()=>{const elapsed=area?.querySelector('[data-loading-elapsed]');if(elapsed){const seconds=Math.floor((Date.now()-started)/1000);elapsed.textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}},1000);
 button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=I('book')+'<span>Typesetting…</span>';
 if(area)area.innerHTML=loadingHTML('Your book is taking shape','Setting the type, resolving the contents, and preparing your PDF.',{kind:'typeset'});
 try{
  const pdf=await compilePDF(bookTex(snapshot),connection,{signal:controller.signal});download(snapshot.title+'.pdf',pdf);dialog.close();toast('Your LaTeX PDF is ready.');
 }catch(error){
  if(controller.signal.aborted&&controller.signal.reason?.name!=='TimeoutError')return;
  if(area?.isConnected)area.innerHTML=`<div class="compiler-summary">${motionGraphic('typeset','service-vector')}<div><h3>Let’s get these pages ready</h3><p>${esc(error.name==='TypeError'?'The local compiler could not be reached. Check that it is running and this studio has local-network access.':error.message)}</p></div></div>`;
  throw error;
 }finally{clearInterval(clock);clearTimeout(deadline);dialog.removeEventListener('close',cancel);if(compileSession?.controller===controller)compileSession=null;peers.forEach(peer=>{if(peer.isConnected)peer.disabled=false;});if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=I('book')+'<span>Compile PDF</span>';}}
}
async function generateCover(){if(busy)throw Error('Wait for the current AI request to finish.');const p=project(),c=state.connections.find(c=>providerFor(c).image&&c.id===state.activeConnection)||state.connections.find(c=>providerFor(c).image);if(!c){modal('An original cover is already yours',`<p>Your vector cover is ready to export. Connect an image provider to add generated artwork.</p>`,B('close-dialog','Keep vector cover')+B('go-image-hub','Connect image provider','arrow','primary'));return;}const key=await getKey(c);if(!await consent(c,'your book title, premise and chosen cover direction for one image'))return;busy=true;setBusy(true,'Creating your cover artwork');try{const[w,h]=trimOf(p);let img=await generateImage(c,key,`Create original literary cover art for ${p.title}. Premise: ${p.premise}. Mood: ${p.style}. Cover direction: ${p.coverDesign||'Orbit'}. Palette: ${coverOptions(p).bg||p.color}; title position: ${coverOptions(p).titlePosition}. Leave generous negative space around that title area. No lettering, logos or watermarks. Strong composition, clear negative space for the title, subtle original imagery. Canvas ratio ${w}:${h}.`,w/h);if(!/^data:image\/(png|jpeg|webp);base64,|^https:\/\//.test(img))throw Error('The provider returned an unsupported image format.');if(img.startsWith('https://')){const response=await fetch(img,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('The generated image could not be downloaded. Your vector cover is intact.');const blob=await response.blob();if(!/^image\/(png|jpeg|webp)$/.test(blob.type)||blob.size>10000000)throw Error('Choose a smaller cover image under 10 MB.');img=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}if(state.projects.includes(p)){p.image=img;save();if(project()?.id===p.id)render();toast('Your cover artwork is ready.');}}finally{busy=false;setBusy(false);}}
