let paletteItems=[],paletteSelection=0;
function commandPalette(){modal('Find your place',`<div class="command-search">${I('search')}<input id="command-input" type="search" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="command-results" aria-label="Find books, chapters, characters, or an action" autocomplete="off"></div><p class="command-hint">Search your books, chapters, characters, world notes, and actions.</p><div id="command-results" role="listbox" aria-label="Search results"></div><footer class="command-footer"><span><kbd>↑</kbd><kbd>↓</kbd> to move</span><span><kbd>Enter</kbd> to open</span><span><kbd>Esc</kbd> to close</span></footer>`);dialog.className='command-dialog';updateCommands('');document.querySelector('#command-input').focus();}
function updateCommands(input){const commands=[{kind:'action',action:'open-apps',title:isNative()?'Device tools':'Download BookWiz apps',detail:'Widgets, reminders, device models and downloads',icon:'download'},{kind:'action',action:'new-project',title:'Start a new book',detail:'Book wizard',icon:'plus'},{kind:'action',action:'reader',title:'Read the manuscript',detail:project()?.title||'Your reading room',icon:'book'},{kind:'action',action:'version-history',title:'Chapter versions',detail:'Return to an earlier draft',icon:'clock'},{kind:'action',action:'quick-note',title:'Capture a thought',detail:'A note for your current book',icon:'note'},{kind:'action',action:'export-workspace',title:'Back up your workspace',detail:'Download your books as JSON',icon:'shield'},{kind:'action',action:'appearance',title:'Appearance & writing preferences',detail:'Platform, color, and accessibility',icon:'settings'},{kind:'action',action:'open-draft-flow',title:'Draft Flow',detail:'Steer a continuation, pin a phrase and explore alternatives',icon:'feather'},{kind:'action',action:'shortcuts',title:'Keyboard shortcuts',detail:'A few useful ways around',icon:'help'}].filter(c=>!['reader','version-history','quick-note','open-draft-flow'].includes(c.action)||project());const q=input.toLocaleLowerCase().trim();paletteItems=[...searchWorkspace(state.projects,input),...commands.filter(c=>!q||(c.title+' '+c.detail).toLocaleLowerCase().includes(q))];paletteSelection=0;const results=document.querySelector('#command-results');results.innerHTML=paletteItems.map((r,i)=>`<button role="option" id="command-result-${i}" aria-selected="${i===0}" class="command-result ${i===0?'selected':''}" data-action="command-select" data-index="${i}">${I(r.icon||({book:'book',chapter:'file',character:'users',world:'world',note:'note'}[r.kind]))}<span class="grow"><strong>${esc(r.title)}</strong><small>${esc(r.detail||'')}</small></span><span class="result-kind">${r.kind==='action'?'Action':r.kind}</span></button>`).join('')||'<div class="command-empty">No matching pages. Try another word.</div>';const field=document.querySelector('#command-input');if(paletteItems.length)field.setAttribute('aria-activedescendant','command-result-0');else field.removeAttribute('aria-activedescendant');}
function moveCommand(delta){if(!paletteItems.length)return;paletteSelection=(paletteSelection+delta+paletteItems.length)%paletteItems.length;document.querySelectorAll('.command-result').forEach((b,i)=>{b.classList.toggle('selected',i===paletteSelection);b.setAttribute('aria-selected',String(i===paletteSelection));});const active=document.querySelector('#command-result-'+paletteSelection);document.querySelector('#command-input').setAttribute('aria-activedescendant',active.id);active.scrollIntoView?.({block:'nearest'});}
async function selectCommand(index){const r=paletteItems[index];if(!r)return;dialog.close();if(r.kind==='action'){await actions[r.action]();return;}activeId=r.id;const p=project();chapterIndex=r.kind==='chapter'?r.index:Math.min(p.lastChapter||0,p.chapters.length-1);p.lastChapter=chapterIndex;state.settings.lastProject=activeId;studioTab=({character:'characters',world:'world',note:'notes'}[r.kind])||'draft';route='studio';drawer=null;save();render();scrollWorkspaceToTop();if(r.kind==='chapter')document.querySelector('#editor')?.focus();}
function readerHTML(){const p=project();if(!p)return `<div class="page empty"><h1>Your reading room</h1><p>Open a book from your library.</p>${B('reader-library','Go to the library','library','primary')}</div>`;chapterIndex=Math.min(chapterIndex,p.chapters.length-1);const c=p.chapters[chapterIndex];return `<div class="reading-page"><div class="reader-controls"><div class="row wrap gap8">${writingAnchor?'':B('reader-back','Back to writing','pen','secondary')}<select id="reader-chapter" aria-label="Reading chapter">${p.chapters.map((ch,i)=>`<option value="${i}" ${i===chapterIndex?'selected':''}>${i+1}. ${esc(ch.title)}</option>`).join('')}</select></div><div class="row gap8"><button class="icon-btn" data-action="font-step" data-value="-1" aria-label="Decrease reading text size">A−</button><button class="icon-btn" data-action="font-step" data-value="1" aria-label="Increase reading text size">A+</button>${B('read-aloud','Read aloud','volume','quiet')}</div></div><div class="reader-book-title">${esc(p.title)} <span>by ${esc(p.author)}</span></div><article class="reader-paper"><p class="chapter-kicker">CHAPTER ${chapterIndex+1}</p><h1>${esc(c.title)}</h1><div class="reader-prose">${c.text?cleanHTML(c.text):`<p class="muted">This chapter is ready for its first words.</p>`}</div></article><footer class="reader-footer">${B('reader-prev','Previous chapter','chevron','secondary',chapterIndex===0?'disabled':'')}<span>${chapterIndex+1} of ${p.chapters.length}</span>${B('reader-next','Next chapter','arrow','secondary',chapterIndex===p.chapters.length-1?'disabled':'')}</footer></div>`;}
