function versionHistory(){const p=project();if(!p)return;const c=p.chapters[chapterIndex];const revisions=(p.revisions||[]).filter(r=>r.chapterId===c.id);modal('Chapter versions',`<p><strong>${esc(c.title)}</strong></p><p class="muted" style="margin-top:8px">A version is kept before AI additions and bulk edits. You can save one whenever you reach a useful stopping point. Up to 12 versions per book are kept within the local storage budget.</p><div class="version-list">${revisions.map(r=>`<div class="version-item"><div>${I('clock')}</div><div class="grow"><strong>${esc(r.reason)}</strong><small>${new Date(r.date).toLocaleString()} · ${words(plain(r.text)).toLocaleString()} words</small></div>${B('preview-version','Preview','','secondary',`data-id="${r.id}"`)}</div>`).join('')||'<div class="version-empty">No earlier version of this chapter yet. Save a version before trying a different direction.</div>'}</div>`,B('close-dialog','Close')+B('save-version','Save current version','plus','primary'));dialog.className='version-dialog';}
