async function handleReference(input){const file=input.files?.[0],flow=wizard;if(!file||!flow)return;const status=document.querySelector('#reference-status');try{if(file.size>10*1024*1024)throw Error('Choose a reference smaller than 10 MB.');status.textContent='Reading on this device…';const bytes=await file.arrayBuffer(),key=await digest(bytes);let text=await cacheGet('reference:'+key);const cached=!!text;if(!text){if(file.name.toLowerCase().endsWith('.pdf')){text=await extractPdfText(bytes);}else text=new TextDecoder().decode(bytes);if(text.length>500000)throw Error('Choose a reference excerpt under 500,000 characters.');await cachePut('reference:'+key,text,{kind:'reference',days:30});}if(wizard!==flow)return;if(flow.references.some(r=>r.hash===key)){status.textContent='This reference is already in your brief.';return;}flow.references.push({name:file.name,text,hash:key});persistWizard();status.textContent=`${file.name} · ${words(text).toLocaleString()} words · ${cached?'reused from local cache':'parsed and cached locally'}`;}catch(error){if(status?.isConnected)status.textContent=error.message;}}
const sessionTicker=setInterval(tickSession,1000);sessionTicker.unref?.();
