window.addEventListener('beforeunload',flushWizardCache);
document.addEventListener('keydown',event=>{if(!menuOpen)return;if(event.key==='Escape'){event.preventDefault();closeMenu();return;}if(event.key==='Tab'){const items=[...document.querySelectorAll('.sidebar button,.sidebar a')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});

function localGuide(){const run=runtimeInfo();modal('Choose a local writing companion',`<p>${run.native?`You’re using the ${esc(run.name)}.`:'You’re using BookWiz in a browser.'} ${deviceCapabilities().apple?'Apple Intelligence connects directly in the model hub on a compatible device. Other local models use an installed runtime.':'For a local model, connect an installed runtime or use Apple Intelligence in a compatible iPhone/iPad app.'}</p><details class="setting-details" open><summary>Computer · Ollama or LM Studio</summary><ol class="setup-steps"><li><div>Install <a href="https://ollama.com/download" target="_blank" rel="noopener">Ollama</a> or <a href="https://lmstudio.ai/download" target="_blank" rel="noopener">LM Studio</a>.</div></li><li><div>Download a model your computer can run. In Ollama, use <code>ollama pull llama3.2</code>. In LM Studio, load a compatible model and start its server.</div></li><li><div>Allow this BookWiz origin in the runtime’s CORS settings. For Ollama, set <code>OLLAMA_ORIGINS</code> to the address below before starting the server.</div></li><li><div>Add a connection. Ollama: <code>http://localhost:11434/v1</code>. LM Studio: <code>http://localhost:1234/v1</code>. Use the exact served model ID. A local API key is usually unnecessary.</div></li></ol></details><details class="setting-details" ${run.platform==='ios'?'open':''}><summary>iPhone & iPad</summary><p class="small muted">A compatible mobile runtime must explicitly expose a local OpenAI-compatible API. Keep that runtime active, load a model suited to available memory, and enter its loopback endpoint. In the installed iPhone/iPad app, choose Apple Intelligence in the model hub. It requires iOS/iPadOS 26 or later, a compatible device, supported language and downloaded models. Other local models need a compatible runtime.</p><a class="text-link" href="https://huggingface.co/docs/mlx/index" target="_blank" rel="noopener">MLX model and runtime guidance ${I('external')}</a></details><details class="setting-details" ${run.platform==='android'?'open':''}><summary>Android</summary><p class="small muted">Use a runtime that can serve an OpenAI-compatible local API, such as a compatible llama.cpp server. Load a model supported by your hardware, start its local server, and add the loopback endpoint below. Standalone chat apps without an API cannot be used as BookWiz providers.</p><a class="text-link" href="https://github.com/ggml-org/llama.cpp/tree/master/tools/server" target="_blank" rel="noopener">Official llama.cpp server guide ${I('external')}</a></details><details class="setting-details"><summary>Importing model files</summary><p class="small muted">Download model weights from trusted publishers, check their license and memory requirements, and import them into your chosen runtime. GGUF, MLX and platform-specific formats are different. BookWiz does not upload model files to a server or load arbitrary weights itself.</p></details><label class="field" style="margin-top:25px"><span>This workspace’s origin</span><input id="local-origin" value="${esc(location.origin)}" readonly></label><p class="small muted" style="margin-top:12px">Local runtimes use device memory and battery. A browser or device may ask for local-network permission. Only allow a runtime you trust.</p>`,B('close-dialog','Close')+B('copy-local-origin','Copy origin','file','secondary')+B('connect-local','Add local connection','cpu','primary'));}
Object.assign(actions,{'local-guide':localGuide,'connect-local':()=>providerSetup('custom'),'copy-local-origin':async()=>{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(location.origin);toast('Workspace origin copied.');}else{document.querySelector('#local-origin')?.select();toast('Select and copy the displayed origin.');}}});

async function aiJSON(prompt,description,system,maxTokens=4096){if(busy)throw Error('Wait for the current model request.');const c=activeConnection();if(!isTextModel(c)){route='hub';render();return null;}const key=await getKey(c),flow=route==='wizard'?wizard:null,origin=flow?(flow.projectId&&state.projects.find(p=>p.id===flow.projectId)):project();if(!await consent(c,description+' in up to two short requests if a response needs repair'))return null;busy=true;setBusy(true,'Shaping an editable suggestion');try{return await completeJSON((text,tokens)=>generate(c,key,text,system,tokens),{prompt,maxTokens,onRecovery:response=>{if(flow){flow.modelRecoveries??=[];flow.modelRecoveries.push(response);flow.modelRecoveries=flow.modelRecoveries.slice(-3);if(wizard===flow)persistWizard();}else if(origin&&state.projects.includes(origin)){origin.notes.unshift({id:uid(),date:Date.now(),text:'Incomplete model response — not applied to your manuscript.\n\n'+response.text});save();}}});}catch(error){if(error.name==='OutputLimitError'||error instanceof SyntaxError)throw Error('The model could not finish this structured suggestion. Partial replies are saved '+(flow?'in this setup.':'in Notes.')+' Try a shorter request or another model.');throw error;}finally{busy=false;setBusy(false);if(flow&&wizard===flow&&route==='wizard')refreshWizardAside();}}
function showSetupRecovery(){const responses=wizard?.modelRecoveries||[];modal('Saved suggestion replies',`<p>Incomplete replies are kept here. They have not replaced your premise or story notes.</p>${responses.map(r=>`<details class="setting-details"><summary>${esc(r.message)}</summary><pre style="white-space:pre-wrap;font:12px/1.8 var(--ui-font)">${esc(r.text||'No readable text was returned.')}</pre></details>`).join('')}`,B('close-dialog','Close'));}
Object.assign(actions,{'setup-recovery':showSetupRecovery});

function openAppFeature(id){menuOpen=false;drawer=null;route='apps';render();const feature=document.getElementById('feature-'+id),disclosure=feature?.closest('details');if(disclosure)disclosure.open=true;feature?.scrollIntoView?.({block:'center',behavior:document.documentElement.classList.contains('reduce-motion')?'auto':'smooth'});}
Object.assign(actions,{'studio-more':()=>modal('Your book',`<div class="studio-book-menu">${B('book-brief','Book brief','file','secondary')}${B('outline','Chapter outline','list','secondary')}${B('open-red-pen','The Red Pen','pen','secondary')}${B('preview-book','Preview book','book','secondary')}${B('generate-book','Draft chapters','feather','secondary')}</div>`),'apps-downloads':()=>document.getElementById('app-downloads')?.scrollIntoView?.({block:'start'}),'open-apps':()=>{menuOpen=false;route='apps';render();},'reminder-preferences':()=>{if(!deviceCapabilities().reminders){openAppFeature('reminders');return;}route='settings';settingTab='preferences';render();const details=document.querySelector('.reminder-settings');if(details){details.open=true;details.scrollIntoView({block:'center'});details.querySelector('summary')?.focus();}},'device-apple-model':()=>providerSetup('apple-device'),'device-print':()=>{if(!project()){toast('Open or create a book before preparing its pages.');route='library';render();return;}route='covers';render();document.querySelector('.export-options')?.scrollIntoView({block:'center'});}});
window.addEventListener('bookwiz-open-backup',event=>{try{importBackupText(event.detail?.text);}catch(error){toast(error.message||'This backup could not be opened.');}});
window.addEventListener('bookwiz-device-command',event=>{const command=event.detail?.action;if(['new-project','import-backup','export-workspace','print-book'].includes(command)){if(command==='print-book'&&!project()){toast('Open a book before printing.');return;}Promise.resolve(actions[command]()).catch(reportError);}else if(['library','studio','covers','apps','settings'].includes(command)){route=command;render();}});
window.BookWizDeviceBack=()=>{if(dialog.open){dialog.close();return true;}if(document.body.classList.contains('zen')){document.body.classList.remove('zen');return true;}if(menuOpen){closeMenu();return true;}if(drawer){drawer=null;render();return true;}if(route==='wizard'&&wizard){if(wizard.step>0&&!busy)actions['wizard-back']();else actions['cancel-wizard']();return true;}if(route!=='library'){if(writingAnchor&&pageTrail.canBack&&navigateTrail(-1))return true;if(wizard)syncWizard();save();route='library';render();return true;}return false;};
const coverHistory=new Map();let coverSaveTimer;
function coverSnapshot(p){return Object.fromEntries(['title','subtitle','author','blurb','imprintName','color','coverDesign','image','coverOptions'].map(k=>[k,k==='coverOptions'?structuredClone(p[k]||{}):p[k]]));}
function rememberCover(p,force=false){let h=coverHistory.get(p.id);if(!h){h={items:[],at:0};coverHistory.set(p.id,h);}if(force||Date.now()-h.at>1500){h.items.push(coverSnapshot(p));h.items=h.items.slice(-12);h.at=Date.now();}}
function updateCoverForm(form){const p=project();if(!p)return;if(!form.checkValidity()){const status=document.querySelector('#cover-save-status');if(status)status.textContent='Complete the title and author before saving.';return;}rememberCover(p);Object.assign(p,coverFormValues(form,p));p.updated=Date.now();for(const swatch of form.querySelectorAll('[data-action="cover-color"]'))swatch.setAttribute('aria-pressed',String(coverPaletteSelected(p,swatch.dataset.value)));document.querySelector('#cover-preview').innerHTML=cover(p)+cover(p,true);for(const output of form.querySelectorAll('[data-cover-output]'))output.textContent=coverValue(output.dataset.coverOutput,coverOptions(p)[output.dataset.coverOutput]);const status=document.querySelector('#cover-save-status');if(status)status.textContent='Saving…';clearTimeout(coverSaveTimer);coverSaveTimer=setTimeout(()=>{const success=save();if(status?.isConnected)status.textContent=success?'Saved on this device':'Not saved · export a backup';},250);coverSaveTimer.unref?.();}
function filterCoverGallery(){const filter=document.querySelector('#cover-category')?.value||'All',query=document.querySelector('#cover-design-search')?.value||'',grid=document.querySelector('#cover-gallery');if(grid){grid.innerHTML=coverGallery(project(),filter,query)||'<p class="small muted">No designs match. Try another name or category.</p>';document.querySelector('#cover-gallery-count').textContent=grid.querySelectorAll('.cover-choice').length+' designs · tap a cover to choose';}}
function updateCoverSelectionLabel(){const button=dialog.querySelector('.dialog-actions [data-action="close-dialog"]');if(button&&dialog.classList.contains('cover-gallery-dialog'))button.innerHTML=I('check')+'<span>Done · '+esc(coverDirection(project()?.coverDesign).name)+'</span>';}
function openCoverGallery(){const p=project();modal('Find your cover',`<p class="small muted">Choose a direction, then make it your own. Book details stay with you.</p><div class="cover-gallery-tools"><label class="field"><span>Category</span><select id="cover-category">${opts(['All',...new Set(coverDesigns.map(d=>d.category))],'All')}</select></label><label class="field"><span>Find a design</span><input type="search" id="cover-design-search"></label></div><span class="small muted" id="cover-gallery-count">32 designs · tap a cover to choose</span><div id="cover-gallery" class="cover-gallery">${coverGallery(p)}</div>`,B('close-dialog','Keep this design','check','primary'),{returnToWriting:false});dialog.classList.add('cover-gallery-dialog');updateCoverSelectionLabel();}
Object.assign(actions,{'upload-cover-image':()=>{const p=project(),input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Choose a JPG, PNG or WebP image under 2 MB.');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('This image could not be read.'));reader.readAsDataURL(file);});if(!state.projects.includes(p))return;rememberCover(p,true);p.image=image;save();if(project()?.id===p.id)render();toast('Your artwork is on the cover.');}catch(error){toast(error.message);}};input.click();},'cover-gallery':openCoverGallery,'choose-cover-design':el=>{const p=project(),d=coverDirection(el.dataset.id);rememberCover(p,true);p.coverDesign=d.id;p.color=d.palette;p.coverOptions={};p.updated=Date.now();save();render();for(const card of dialog.querySelectorAll('.cover-choice')){card.classList.toggle('selected',card.dataset.id===d.id);card.setAttribute('aria-pressed',String(card.dataset.id===d.id));}updateCoverSelectionLabel();},'cover-undo':()=>{const p=project(),h=coverHistory.get(p.id),last=h?.items.pop();if(!last){toast('Your cover has no earlier changes in this session.');return;}Object.assign(p,last);h.at=Date.now();save();render();},'reset-cover-style':()=>{const p=project();rememberCover(p,true);p.coverOptions={};p.color=coverDirection(p.coverDesign).palette;save();render();},'remove-cover-image':()=>{const p=project();rememberCover(p,true);delete p.image;save();render();}});
let reminderSignature='',reminderBusy=false,reminderQueued=false,reminderWaiting=false,reminderTimer;
function syncWritingReminders(requestPermission=false){const host=window.BookWizHost;if(!host?.scheduleReminders)return;if(reminderBusy){reminderQueued=true;return;}let p;try{p=reminderPreferences(state.settings.reminders);}catch{return;}const payload={...p,plans:buildReminderPlan(p),requestPermission};const signature=JSON.stringify(payload);if(!requestPermission&&signature===reminderSignature)return;reminderSignature=signature;reminderBusy=true;clearTimeout(reminderTimer);const fail=error=>{reminderSignature='';window.dispatchEvent(new CustomEvent('bookwiz-reminder-status',{detail:{status:'error',enabled:false}}));if(error)reportError(error);};reminderTimer=setTimeout(()=>fail(Error('The device did not confirm your reminders. Try again or check notification access in device Settings.')),15000);reminderTimer.unref?.();try{Promise.resolve(host.scheduleReminders(payload)).catch(fail);}catch(error){fail(error);}}
function saveReminderForm(){const form=document.querySelector('#reminder-form');if(!form?.checkValidity())return false;try{const values=Object.fromEntries(new FormData(form));state.settings.reminders=reminderPreferences({...reminderDefaults,...state.settings.reminders,...values});save();document.querySelector('#reminder-status').textContent='Saved on this device.';return true;}catch(error){document.querySelector('#reminder-status').textContent=error.message;return false;}}
function renderReminderSettings(){if(route==='settings'&&settingTab==='preferences'){render();const details=document.querySelector('.reminder-settings');if(details)details.open=true;}}
window.addEventListener('bookwiz-reminder-status',event=>{const d=event.detail;if(!['granted','denied','error'].includes(d?.status))return;clearTimeout(reminderTimer);reminderBusy=false;if(reminderQueued){reminderQueued=false;syncWritingReminders();return;}const previous=!!state.settings.reminders?.enabled;state.settings.reminders={...reminderDefaults,...state.settings.reminders,enabled:d.status==='granted'&&d.enabled===true};save();if(reminderWaiting||previous!==state.settings.reminders.enabled){reminderWaiting=false;renderReminderSettings();}const status=document.querySelector('#reminder-status');if(status)status.textContent=d.status==='denied'?'Notifications are not allowed. You can change access in your device Settings.':d.status==='error'?'Reminders could not be scheduled. Try again or review device Settings.':d.enabled?'Your writing reminders are scheduled.':'Reminders are off.';if(reminderQueued){reminderQueued=false;syncWritingReminders();}});
window.addEventListener('bookwiz-notification-test',event=>{const message=event.detail?.sent?'Test notification sent. Check your notification shade.':'Notifications are blocked. Enable BookWiz and Writing reminders in device Settings.';const status=document.querySelector('#reminder-status');if(status)status.textContent=message;toast(message);});
Object.assign(actions,{'test-notification':()=>window.BookWizHost?.testNotification?.(),'enable-reminders':()=>{if(!saveReminderForm())return;state.settings.reminders.enabled=true;save();reminderWaiting=true;syncWritingReminders(true);},'disable-reminders':()=>{state.settings.reminders={...reminderDefaults,...state.settings.reminders,enabled:false};save();renderReminderSettings();syncWritingReminders();},'pause-reminders':()=>{if(!saveReminderForm())return;state.settings.reminders.pausedUntil=Date.now()+7*86400000;save();renderReminderSettings();syncWritingReminders();},'resume-reminders':()=>{if(!saveReminderForm())return;state.settings.reminders.pausedUntil=0;save();renderReminderSettings();syncWritingReminders();}});
let widgetTimer;function scheduleWidgets(){if(!window.BookWizHost?.updateWidgets)return;clearTimeout(widgetTimer);widgetTimer=setTimeout(()=>{try{Promise.resolve(window.BookWizHost.updateWidgets(widgetSnapshot(state,project(),today()))).catch(reportError);}catch(error){reportError(error);}},1000);widgetTimer.unref?.();}
function openWidgetTarget(value){
 const target=widgetTarget(value);if(!target)return;
 if(dialog.open)dialog.close();menuOpen=false;drawer=null;document.body.classList.remove('zen');document.querySelector('.sidebar-backdrop')?.remove();query='';
 const requestedId=target.projectId||(target.action==='session'&&state.writingSession&&!state.writingSession.finished?state.writingSession.projectId:'');
 const requested=requestedId?state.projects.find(p=>p.id===requestedId&&!p.archived&&!p.sample):null;
 const current=requested||state.projects.find(p=>p.id===state.settings.lastProject&&!p.archived&&!p.sample)||state.projects.find(p=>!p.archived&&!p.sample);
 if(requestedId&&!requested){route='library';libraryTab='all';render();toast('That book is no longer on this shelf. Choose another book.');return;}
 if(current){activeId=current.id;chapterIndex=Math.max(0,current.chapters.findIndex(c=>c.id===target.chapterId));if(!target.chapterId)chapterIndex=Math.min(current.lastChapter||0,current.chapters.length-1);current.lastChapter=chapterIndex;state.settings.lastProject=activeId;}
 if(target.action==='reminders'){actions['reminder-preferences']();return;}
 if(target.action==='clock'){window.BookWizHost?.openClock?.();return;}
 if(target.action==='new-book'){actions['new-project']();scrollWorkspaceToTop();return;}
 if(target.action==='capture'){if(!current)activeId=undefined;route=current?'studio':'library';studioTab='notes';render();quickNote();dialog.querySelector('#quick-note-text')?.focus();return;}
 if(target.action==='goal'){route='settings';settingTab='preferences';render();const field=document.querySelector('[name="dailyGoal"]');field?.scrollIntoView?.({block:'center'});field?.focus({preventScroll:true});return;}
 if(target.action==='weekly'){route='library';render();showWeeklyWriting();return;}
 if(target.action==='library'){route='library';libraryTab='all';render();scrollWorkspaceToTop();return;}
 if(!current){route='library';render();scrollWorkspaceToTop();toast('Create a book to begin your next page.');return;}
 studioTab='draft';route=target.action==='publish'?'covers':'studio';save();render();scrollWorkspaceToTop();
 if(target.action==='session')writingSession();
}
function showWeeklyWriting(){
 const data=widgetSnapshot(state,project(),today()),total=data.days.reduce((n,d)=>n+d.words,0),days=data.days.filter(d=>d.words>0).length;
 modal('Your writing week',`<p class="week-summary"><strong>${total.toLocaleString()} words</strong> across ${days} writing ${days===1?'day':'days'} in the last seven days.</p><div class="weekly-days">${data.days.map(d=>`<div><span>${esc(new Date(d.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))}</span><strong>${d.words.toLocaleString()}</strong></div>`).join('')}</div><p class="small muted">Net new words saved on this device. Your own pace, every day.</p>`,B('close-dialog','Close','','secondary')+B('writing-session','Start a session','clock','primary'),{returnToWriting:false});
}
window.addEventListener('bookwiz-widget-action',event=>openWidgetTarget(event.detail));
Object.assign(actions,{'device-details':()=>modal('BookWiz on this device',deviceDetails({B,I}),B('close-dialog','Close')),'access-guide':()=>modal('Your device. Your choice.',`<div class="stack"><div><h3>Files</h3><p>Import and export only the documents you choose in the system picker. BookWiz does not request your whole photo library or shared storage.</p></div><div><h3>Models</h3><p>Approve each writing request before it runs. Apple Intelligence processes requests on a compatible device when enabled in Settings. A local service may ask for local-network access; allow it only for a server you trust.</p></div><div><h3>Voice</h3><p>Read-aloud uses available system voices. To dictate a note, use your device keyboard’s dictation control; its access and processing are managed by the operating system.</p></div><div><h3>Home screen</h3><p>Add widgets from your home screen. Only progress counts and, if enabled, a book title are shared with them. Manuscript text and API keys stay out.</p></div><div><h3>Privacy</h3><p>No tracking, location, contacts or camera access is used. You can review allowed access in your device Settings.</p></div></div>`,B('close-dialog','Close')+(window.BookWizHost?.openSettings?B('device-settings','Open device settings','settings','primary'):'')),'device-settings':()=>window.BookWizHost?.openSettings?.()});
Object.assign(actions,{'save-note':()=>{const text=document.querySelector('#quick-note-text').value.trim();if(!text)return;const note={id:uid(),text,date:Date.now()},p=project();if(p)p.notes.unshift(note);else{state.captureInbox??=[];state.captureInbox.unshift(note);}save();dialog.close();toast('Your thought is safely kept.');},'adopt-capture':el=>{const p=project(),key=el.dataset.source==='watch'?'watchInbox':'captureInbox',note=state[key]?.find(n=>n.id===el.dataset.id);if(!p||!note)return;p.notes.unshift({...note,id:key==='watchInbox'?'watch-'+note.id:note.id});state[key]=state[key].filter(n=>n.id!==note.id);save();quickNote();},'widget-guide':()=>modal('A place on your home screen',`<p>Touch and hold your home screen, choose Widgets, then BookWiz. Choose a size and place it where it feels useful.</p><ul>${(deviceCapabilities().platform==='android'?androidWidgetKinds:widgetKinds).map(name=>`<li>${name}</li>`).join('')}</ul><p class="small muted">Widgets follow your device’s appearance. To show book titles, turn on Show book titles in Settings → Writing. Progress updates when this app saves; each device keeps its own library.</p>`,B('close-dialog','Close'))});
actions['watch-captures']=()=>{quickNote();try{Promise.resolve(window.BookWizHost?.requestWatchNotes?.()).catch(reportError);}catch(error){reportError(error);}};
const nativeWidgetGuide=actions['widget-guide'];actions['widget-guide']=()=>deviceCapabilities().widgets?nativeWidgetGuide():openAppFeature('widgets');
function reportError(e){console.warn('BookWiz:',e.name||'Error');if(dialog.open){const el=dialog.querySelector('#dialog-error');if(el){el.textContent=e.message||'That action could not finish. Your saved work is unchanged.';el.scrollIntoView?.({block:'nearest'});}}else toast(e.message||'That action could not finish. Your saved work is unchanged.');}
async function actionClick(e){const el=e.target.closest('[data-route],[data-action],[data-format]');if(!el)return;if(el.dataset.route){narrationDialogEpoch++;e.preventDefault();menuOpen=false;route=el.dataset.route;query='';drawer=null;document.body.classList.remove('zen');document.querySelector('.sidebar-backdrop')?.remove();if(route==='studio'&&!project())activeId=state.projects.find(p=>p.id===state.settings.lastProject)?.id||state.projects[0]?.id;render();scrollWorkspaceToTop();return;}if(el.dataset.format){e.preventDefault();document.querySelector('#editor')?.focus();document.execCommand(el.dataset.format,false,el.dataset.value||null);document.querySelector('#editor')?.dispatchEvent(new Event('input',{bubbles:true}));return;}if(el.type==='submit'&&el.closest('form'))return;const fn=actions[el.dataset.action];if(fn){e.preventDefault();try{await fn(el);}catch(err){reportError(err);}}}
document.addEventListener('click',actionClick);
document.addEventListener('keydown',e=>{const t=e.target,modifier=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(modifier&&key==='k'){e.preventDefault();if(!dialog.open)commandPalette();else if(dialog.classList.contains('command-dialog'))dialog.close();return;}if(t.id==='command-input'){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();moveCommand(e.key==='ArrowDown'?1:-1);return;}if(e.key==='Enter'){e.preventDefault();selectCommand(paletteSelection).catch(reportError);return;}}if((e.key==='Enter'||e.key===' ')&&t.matches('.cover-stage[role="button"]')){e.preventDefault();actions['open-project'](t);}if(modifier&&!dialog.open&&route==='studio'&&studioTab==='draft'&&t.closest('#editor,#chapter-title,.editor-toolbar')&&(key==='z'||key==='y')){e.preventDefault();moveDraftHistory(key==='y'||e.shiftKey?1:-1);return;}if(e.key==='Escape'&&document.body.classList.contains('zen'))toggleFocus();if(modifier&&key==='s'){e.preventDefault();if(route==='studio'&&!dialog.open)actions['save-version']();else{save();toast('Your workspace is saved on this device.');}}if(modifier&&e.shiftKey&&key==='f'&&route==='studio'&&!dialog.open){e.preventDefault();actions.zen();}if(route==='reader'&&!dialog.open&&!t.closest('input,textarea,select,[contenteditable]')&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();changeChapter(chapterIndex+(e.key==='ArrowLeft'?-1:1));}});
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-format]'))e.preventDefault();});
document.addEventListener('focusin',event=>{if(event.target.closest('#cover-form')&&event.target.matches('input,select,textarea')&&project())rememberCover(project(),true);});
document.addEventListener('input',e=>{const el=e.target;if(el.closest('#profile-form')){clearTimeout(profileSaveTimer);profileSaveTimer=setTimeout(()=>saveProfile(document.querySelector('#profile-form'),true),450);}if(el.closest('#writing-settings,#reading-settings')){clearTimeout(writingSaveTimer);const form=el.closest('form');writingSaveTimer=setTimeout(()=>{if(form.isConnected)saveWriting(form,true);},450);}if(el.id==='cover-design-search')filterCoverGallery();if(el.id==='command-input')updateCommands(el.value);if(el.id==='project-search'){query=el.value;document.querySelector('#books').innerHTML=libraryBooks();}if(el.id==='provider-search'){query=el.value;document.querySelector('#providers').innerHTML=providerCards(providers.filter(p=>(hubTab==='all'||hubTab==='local'&&p.local||hubTab==='image'&&p.image||hubTab==='text'&&p.protocol!=='image'&&!p.local)&&p.name.toLowerCase().includes(query.toLowerCase())));}if(el.closest('#wizard-form')){wizardInput(el);}if(el.id==='legal-search'){const q=el.value.trim();const article=document.querySelector('#legal-document');article.innerHTML=`<h2>${legalDocs[legalTab].title}</h2>${legalDocs[legalTab].html}`;if(q.length>1){const walker=document.createTreeWalker(article,NodeFilter.SHOW_TEXT);const matches=[];while(walker.nextNode())matches.push(walker.currentNode);for(const node of matches){const text=node.textContent;let index=0,found;const frag=document.createDocumentFragment();while((found=text.toLowerCase().indexOf(q.toLowerCase(),index))>=0){frag.append(text.slice(index,found));const mark=document.createElement('mark');mark.textContent=text.slice(found,found+q.length);frag.append(mark);index=found+q.length;}frag.append(text.slice(index));node.replaceWith(frag);}}}if(el.closest('#cover-form'))updateCoverForm(el.closest('form'));if(el.id==='latex-endpoint'){state.settings.latexEndpoint=el.value;save();}});
document.addEventListener('change',async e=>{if(e.target.id==='studio-section'){studioTab=e.target.value;render();return;}if(e.target.id==='mobile-chapter'){changeChapter(Number(e.target.value));return;}if(e.target.closest('#narration-form')){narrator.stop();saveSpeechForm();renderNarrationForm();return;}if(e.target.closest('#cover-form'))updateCoverForm(e.target.closest('form'));if(e.target.id==='proof-zoom'&&proofState){proofState.zoom=e.target.value;scaleProof();return;}if(e.target.id==='world-filter'){worldFilter=e.target.value;render();}if(e.target.id==='cover-category')filterCoverGallery();if(e.target.closest('#reminder-form')&&saveReminderForm())syncWritingReminders();if(e.target.closest('#profile-form'))saveProfile(e.target.closest('form'),true);if(e.target.closest('#writing-settings,#reading-settings'))saveWriting(e.target.closest('form'),true);if(e.target.closest('#defaults-form'))saveDefaults(e.target.closest('form'));if(e.target.id==='proof-page'&&proofState){const p=proofState.p;loadProofSection(e.target.value);return;}if(e.target.closest('#wizard-form')&&['language','genre','trim','publicationStyle','authorStyle','imprintChoice'].includes(e.target.name)){syncWizard();render();} if(e.target.id==='library-sort'){state.settings.librarySort=e.target.value;save();document.querySelector('#books').innerHTML=libraryBooks();}if(e.target.id==='reader-chapter')changeChapter(Number(e.target.value));if(e.target.id==='cover-project'){activeId=e.target.value;state.settings.lastProject=activeId;save();render();}if(e.target.id==='reference-upload')await handleReference(e.target);});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{
if(form.id==='wizard-form')await submitWizard();
if(form.id==='book-brief-form')saveBookBrief(form);
if(form.id==='connection-form'){const d=Object.fromEntries(new FormData(form)),provider=providers.find(p=>p.id===form.dataset.provider);const url=new URL(d.endpoint);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw Error('Use HTTPS, or a localhost HTTP endpoint.');const previous=state.connections.find(c=>c.id===form.dataset.connection);const c={...previous,id:previous?.id||uid(),provider:provider.id,name:d.name.trim(),model:d.model.trim(),endpoint:d.endpoint.replace(/\/$/,''),replyLimit:Number(d.replyLimit)||4096,verified:null};if(d.passphrase&&d.key)c.vault=await encryptKey(d.key,d.passphrase);else if(d.key)delete c.vault;if(d.key||!previous)sessionKeys.set(c.id,d.key);if(previous)state.connections[state.connections.indexOf(previous)]=c;else state.connections.push(c);if((!state.activeConnection||wizardIntent)&&provider.protocol!=='image')state.activeConnection=c.id;save();dialog.close();if(wizardIntent&&isTextModel(c))openStoryWizard();else render();toast('Connection saved. Verify it before writing.');}
if(form.id==='chapter-form'){const d=Object.fromEntries(new FormData(form));project().chapters.push({...d,id:uid(),text:'',status:'Planned'});project().chapterCount=project().chapters.length;registerContextChange(project(),'outline','A chapter was added.');chapterIndex=project().chapters.length-1;save();dialog.close();render();}
if(form.id==='entity-form')saveStoryEntity(form);
if(form.id==='chat-form'){const text=document.querySelector('#chat-input').value.trim();if(text)await sendChat(text);}
if(form.id==='cover-form'){updateCoverForm(form);save();toast('Your cover is saved.');}
if(form.id==='profile-form')saveProfile(form);
if(['writing-settings','reading-settings'].includes(form.id))saveWriting(form);
if(form.id==='defaults-form')saveDefaults(form);if(form.id==='reminder-form'&&saveReminderForm())syncWritingReminders();
}catch(err){reportError(err);}});
function bindEditor(){const editor=document.querySelector('#editor');if(!editor)return;draftHistory.sync(chapterKey(),project().chapters[chapterIndex]);updateDraftButtons();let editStart=editor.innerHTML;editor.addEventListener('focus',()=>{editStart=editor.innerHTML;});editor.addEventListener('blur',()=>{if(editor.innerHTML!==editStart){const p=project();if(p.chapters.slice(chapterIndex+1).some(c=>plain(c.text).trim())){registerContextChange(p,'manuscript edit','Chapter '+(chapterIndex+1)+' was edited; check later chapters for affected facts.',{fromIndex:chapterIndex+1});save();updateJobUI(p);}}});let previous=words(plain(project().chapters[chapterIndex].text));editor.addEventListener('input',()=>{const p=project(),c=p.chapters[chapterIndex];if(Date.now()-(autoRevisionTimes.get(c.id)||0)>300000){addRevision(p,c,'Before editing');autoRevisionTimes.set(c.id,Date.now());}c.text=cleanHTML(editor.innerHTML);draftHistory.sync(chapterKey(p,c),c,{typing:true});updateDraftButtons();if((p.contextRevision||0)>0){p.continuityReview&&(p.continuityReview.stale=true);}c.status='Drafting';p.sample=false;p.updated=Date.now();const n=words(plain(c.text));state.activity[today()]=(state.activity[today()]||0)+Math.max(0,n-previous);previous=n;document.querySelector('#word-count').textContent=n.toLocaleString();save();});editor.addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));});const title=document.querySelector('#chapter-title');let titleStart=title.value;title.addEventListener('focus',()=>{titleStart=title.value;});title.addEventListener('input',()=>{const p=project(),c=p.chapters[chapterIndex];c.title=title.value;p.updated=Date.now();draftHistory.sync(chapterKey(),c,{typing:'title'});updateDraftButtons();save();});title.addEventListener('change',()=>{const p=project(),c=p.chapters[chapterIndex];if(c.title!==title.value){c.title=title.value;draftHistory.sync(chapterKey(),c,{typing:'title'});updateDraftButtons();}if(titleStart!==title.value){registerContextChange(p,'chapter title',title.value,{fromIndex:chapterIndex});titleStart=title.value;}save();});}
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(['library','studio','reader','covers','hub','settings','legal','apps'].includes(hash)){route=hash;render();}});
window.addEventListener('beforeunload',()=>{narrator.stop();save();if('speechSynthesis'in window)speechSynthesis.cancel();});
window.addEventListener('storage',e=>{if(e.key==='bookwiz-v1')toast('This workspace changed in another tab. Export current work before reloading.');});
if(['library','studio','reader','covers','hub','settings','legal','apps'].includes(location.hash.slice(1)))route=location.hash.slice(1);
save();render();
if(!isNative()&&'serviceWorker'in navigator&&window.isSecureContext){navigator.serviceWorker.register('./sw.js').catch(()=>{});}

for(const query of ['(prefers-color-scheme: dark)','(prefers-reduced-transparency: reduce)','(prefers-reduced-motion: reduce)'])window.matchMedia?.(query).addEventListener?.('change',()=>applyAppearance(state.settings));
if(window.visualViewport){const updateKeyboard=()=>{if(!window.BookWizHost?.managesKeyboardInsets)document.documentElement.toggleAttribute('data-keyboard-open',window.innerHeight-window.visualViewport.height>150);};window.visualViewport.addEventListener('resize',updateKeyboard);}

window.addEventListener('bookwiz-native-error',e=>toast(e.detail||'The native action could not finish.'));

window.addEventListener('bookwiz-watch-notes',event=>{if(!Array.isArray(event.detail))return;state.watchInbox??=[];state.seenWatchNotes??=[];const ack=[];let added=0;for(const n of event.detail){if(!n||typeof n.id!=='string'||typeof n.text!=='string'||!n.text.trim()||n.text.length>20000)continue;ack.push(n.id);if(state.seenWatchNotes.includes(n.id))continue;const date=Number.isFinite(n.date)?n.date*1000:Date.now(),p=state.projects.find(p=>p.id===n.projectId);if(p){p.notes.unshift({id:'watch-'+n.id,text:n.text,date});p.updated=Date.now();}else state.watchInbox.push({id:n.id,text:n.text,date});state.seenWatchNotes.push(n.id);added++;}state.seenWatchNotes=state.seenWatchNotes.slice(-500);if(save()){window.BookWizHost?.ackWatchNotes?.(ack);if(added){if(dialog.open&&dialog.querySelector('#quick-note-text')&&!dialog.querySelector('#quick-note-text').value)quickNote();toast(added+' watch capture(s) received. Open Quick capture to review unassigned thoughts.');}}});
try{Promise.resolve(window.BookWizHost?.requestWatchNotes?.()).catch(reportError);}catch(error){reportError(error);}

let navigationBreakpoint=window.innerWidth<=900;window.addEventListener('resize',()=>{const next=window.innerWidth<=900;if(next!==navigationBreakpoint){navigationBreakpoint=next;menuOpen=false;if(wizard)syncWizard();render();}});

scheduleWidgets();
window.addEventListener('visibilitychange',()=>{if(!document.hidden)scheduleWidgets();});

document.addEventListener('click',event=>{for(const menu of document.querySelectorAll('.studio-tools[open]'))if(!menu.contains(event.target))menu.open=false;});
document.addEventListener('keydown',event=>{if(event.key==='Escape')for(const menu of document.querySelectorAll('.studio-tools[open]')){menu.open=false;menu.querySelector('summary').focus();}});

syncWritingReminders();
document.addEventListener('visibilitychange',()=>{if(!document.hidden){reminderSignature='';syncWritingReminders();if(route==='hub'&&Date.now()-lastLocalCheck>30000)void scanLocalModels();}});

document.addEventListener('invalid',event=>{if(event.target.closest('#cover-form')){const group=event.target.closest('details');if(group)group.open=true;}},true);

window.addEventListener('focus',()=>{if(dialog.open&&document.querySelector('#compiler-state')&&!compileSession)void refreshCompiler();});
installControlFeedback(document);installFluidControls(document);
window.BookWizWidgetReady=true;window.BookWizHost?.widgetReady?.();
window.BookWizHost?.ready?.();
